// 500 ideas across 16 categories. Fields: id, category, text, source.
const FACTS = [
  {"id": 1, "category": "Trading Psychology", "text": "Think in probabilities, not predictions. Any single trade can lose; your edge only shows up across a series of trades. Mark Douglas called this the core shift: stop needing to know what happens next.", "source": "Trading in the Zone — Mark Douglas"},
  {"id": 2, "category": "Trading Psychology", "text": "The five fundamental truths: anything can happen; you don't need to know what happens next to make money; wins and losses are randomly distributed within an edge; an edge is just a higher probability of one outcome; every moment in the market is unique.", "source": "Trading in the Zone — Mark Douglas"},
  {"id": 3, "category": "Trading Psychology", "text": "Don't judge a decision by its outcome. A good process can lose and a reckless bet can win. Annie Duke calls judging by results alone 'resulting' — it teaches you the wrong lessons.", "source": "Thinking in Bets — Annie Duke"},
  {"id": 4, "category": "Trading Psychology", "text": "Ask 'wanna bet?' before stating a market view. The moment real money is attached to a belief, you suddenly audit how much evidence you actually have for it.", "source": "Thinking in Bets — Annie Duke"},
  {"id": 5, "category": "Trading Psychology", "text": "Losses hurt roughly twice as much as equivalent gains feel good. This asymmetry, from prospect theory, is why traders cut winners early and let losers run — the exact opposite of what works.", "source": "Thinking, Fast and Slow — Daniel Kahneman"},
  {"id": 6, "category": "Trading Psychology", "text": "The disposition effect: selling winners to lock in the good feeling and holding losers to avoid admitting the bad one. It feels like discipline. It's ego protection.", "source": "Behavioural finance research — Shefrin & Statman"},
  {"id": 7, "category": "Trading Psychology", "text": "A short track record proves almost nothing. With enough traders flipping coins, some will look like geniuses for years. Ask how big the sample is before crediting skill.", "source": "Fooled by Randomness — Nassim Taleb"},
  {"id": 8, "category": "Trading Psychology", "text": "After the market moves, your brain instantly writes a story explaining why — and the story feels obviously true. It's fiction assembled after the fact. Trade the plan, not the narrative.", "source": "Fooled by Randomness — Nassim Taleb"},
  {"id": 9, "category": "Trading Psychology", "text": "Revenge trading is trying to make the market give your money back. The market doesn't know it has your money. It doesn't know you exist. Close the platform instead.", "source": "The Daily Trading Coach — Brett Steenbarger"},
  {"id": 10, "category": "Trading Psychology", "text": "Journal your emotional state alongside your entries and exits. Steenbarger's finding: most traders' worst losses cluster around identifiable emotional patterns they never noticed until they wrote them down.", "source": "The Daily Trading Coach — Brett Steenbarger"},
  {"id": 11, "category": "Trading Psychology", "text": "Your trading problems are rarely trading problems. They're your everyday psychological patterns — impatience, need for approval, fear of missing out — given a live P&L to express themselves through.", "source": "Enhancing Trader Performance — Brett Steenbarger"},
  {"id": 12, "category": "Trading Psychology", "text": "If a position keeps pulling your attention all day, it's too big. Size positions so you can think clearly, then let the maths of your edge do the work.", "source": "Van Tharp's position-sizing work"},
  {"id": 13, "category": "Trading Psychology", "text": "Ed Seykota's uncomfortable line: 'Everybody gets what they want out of the markets.' Some people want excitement, drama, or punishment more than they want profits — and their results show it.", "source": "Market Wizards — Jack Schwager"},
  {"id": 14, "category": "Trading Psychology", "text": "Schwager interviewed dozens of legendary traders with wildly different methods. The one thing they shared wasn't a strategy — it was ruthless risk control and the discipline to follow their own rules.", "source": "Market Wizards — Jack Schwager"},
  {"id": 15, "category": "Trading Psychology", "text": "The market pays you for discipline, not intelligence. Plenty of brilliant people go broke trading because being clever makes it easier to argue yourself out of your own rules.", "source": "Market Wizards — Jack Schwager"},
  {"id": 16, "category": "Trading Psychology", "text": "Wanting to be right and wanting to make money are different goals that often point in opposite directions. Taking a small loss means admitting error — which is exactly why people avoid it.", "source": "Reminiscences of a Stock Operator — Edwin Lefèvre"},
  {"id": 17, "category": "Trading Psychology", "text": "The market has no idea what your entry price was. Your anchor to that number is entirely in your head — the only question that matters is what the position is worth from here.", "source": "Behavioural finance — anchoring bias"},
  {"id": 18, "category": "Trading Psychology", "text": "Missing a move costs you nothing. An opportunity not taken is not a loss — but the trade you force because you're chasing one usually is.", "source": "Trading wisdom — opportunity vs. loss"},
  {"id": 19, "category": "Trading Psychology", "text": "Overconfidence peaks right after a winning streak — which is exactly when traders size up, loosen rules, and give it all back. Treat a hot streak as a signal to check yourself, not press harder.", "source": "Thinking, Fast and Slow — Daniel Kahneman"},
  {"id": 20, "category": "Trading Psychology", "text": "In a drawdown, cut your size in half. It reduces the damage while you're likely trading worst, and it lowers the emotional temperature enough for judgement to come back.", "source": "The New Market Wizards — Jack Schwager"},
  {"id": 21, "category": "Trading Psychology", "text": "Run a pre-mortem before entering: assume the trade has already failed and write down why. It surfaces the risks your excitement was hiding, while there's still time to size for them.", "source": "Gary Klein's pre-mortem technique"},
  {"id": 22, "category": "Trading Psychology", "text": "You'll look at a chart and see what you already believe. Confirmation bias is strongest when money and ego are on the line — so write your invalidation level down before you look for confirmation.", "source": "Behavioural finance — confirmation bias"},
  {"id": 23, "category": "Trading Psychology", "text": "Boredom is a position risk. Many bad trades exist only because the trader wanted something to happen. If nothing meets your criteria, the correct position size is zero.", "source": "Trading discipline — the no-trade trade"},
  {"id": 24, "category": "Trading Psychology", "text": "A checklist isn't there because you don't know what to do. It's a circuit breaker between impulse and action — it forces the slow brain to sign off on what the fast brain wants.", "source": "The Checklist Manifesto — Atul Gawande"},
  {"id": 25, "category": "Trading Psychology", "text": "Fear is information, not a command. It's telling you something about size, uncertainty, or preparation. Interrogate it — don't obey it blindly and don't suppress it.", "source": "Market Mind Games — Denise Shull"},
  {"id": 26, "category": "Trading Psychology", "text": "Denise Shull's insight from neuroscience: you cannot trade without emotion, because emotion is how the brain assigns value. The goal is to read your feelings as data, not to eliminate them.", "source": "Market Mind Games — Denise Shull"},
  {"id": 27, "category": "Trading Psychology", "text": "Recency bias makes the last few sessions feel like the new permanent reality. Zoom out to the timeframe you actually trade before letting this week rewrite your worldview.", "source": "Behavioural finance — recency bias"},
  {"id": 28, "category": "Trading Psychology", "text": "The best trades often feel uncomfortable at entry, and the most comfortable trades — the obvious ones everyone agrees on — are often already priced in. Comfort is not confirmation.", "source": "The Most Important Thing — Howard Marks"},
  {"id": 29, "category": "Trading Psychology", "text": "Separate your self-worth from your P&L. If a red day means you're a failure, you'll make decisions to protect your identity instead of your capital — and lose both.", "source": "Trading psychology — identity and P&L"},
  {"id": 30, "category": "Trading Psychology", "text": "Build the identity first, then the results follow: 'I am a trader who follows my rules' beats 'I want to make money today.' Every rule-following trade is a vote for that identity, win or lose.", "source": "Atomic Habits applied to trading — James Clear"},
  {"id": 31, "category": "Trading Psychology", "text": "The gap between your backtest self and your live self is where accounts die. A system you can't emotionally execute through its worst drawdown isn't your system — it's someone else's.", "source": "Trade Your Way to Financial Freedom — Van Tharp"},
  {"id": 32, "category": "Trading Psychology", "text": "Trade smaller than you think you should. Almost nobody's trading career ended because their positions were too small — plenty ended because they weren't.", "source": "Trading risk wisdom"},
  {"id": 33, "category": "Trading Psychology", "text": "FOMO is the market's most expensive emotion. By the time a move is exciting enough to create fear of missing out, the low-risk entry is long gone and you're supplying exit liquidity.", "source": "Trading psychology — chasing"},
  {"id": 34, "category": "Trading Psychology", "text": "Amateurs think about how much they can make. Professionals think about how much they can lose. The order you ask those two questions in largely determines which group you end up in.", "source": "Trade Like a Stock Market Wizard — Mark Minervini"},
  {"id": 35, "category": "Trading Psychology", "text": "Patience is a position. Jesse Livermore's biggest money was never made by his thinking — it was made by his sitting. Waiting through the middle of a trend is a skill, not laziness.", "source": "Reminiscences of a Stock Operator — Edwin Lefèvre"},
  {"id": 36, "category": "Stock Trading", "text": "Benjamin Graham's Mr. Market: imagine a manic business partner who offers to buy or sell his share every day at wild prices. You're free to ignore him. His mood swings are your opportunity, never your guide.", "source": "The Intelligent Investor — Benjamin Graham"},
  {"id": 37, "category": "Stock Trading", "text": "Margin of safety is the central idea of investing: pay meaningfully less than your estimate of value, so that being somewhat wrong still leaves you fine. Certainty isn't available; buffer is.", "source": "The Intelligent Investor — Benjamin Graham"},
  {"id": 38, "category": "Stock Trading", "text": "Graham's warning still holds: the investor's chief problem, and even his worst enemy, is likely to be himself. The market transfers money from the impatient to the patient.", "source": "The Intelligent Investor — Benjamin Graham"},
  {"id": 39, "category": "Stock Trading", "text": "Know what you own and why you own it. Peter Lynch found most people spend more time choosing a fridge than a stock — and could explain the fridge better afterwards.", "source": "One Up on Wall Street — Peter Lynch"},
  {"id": 40, "category": "Stock Trading", "text": "Lynch on temperament: the key organ in investing is the stomach, not the brain. Everyone has the intellect to follow the market; not everyone can hold through a 30% drop without panicking.", "source": "One Up on Wall Street — Peter Lynch"},
  {"id": 41, "category": "Stock Trading", "text": "Second-level thinking: first-level thinking says 'it's a good company, buy it.' Second-level asks 'it's a good company, but is that already in the price — and what does the crowd have wrong?'", "source": "The Most Important Thing — Howard Marks"},
  {"id": 42, "category": "Stock Trading", "text": "Howard Marks on risk: risk means more things can happen than will happen. A strategy that worked isn't proof it was safe — you only observed one of many possible outcomes.", "source": "The Most Important Thing — Howard Marks"},
  {"id": 43, "category": "Stock Trading", "text": "You can't predict cycles, but you can locate yourself within one. When credit is loose, optimism is total, and bad deals get funded easily, you don't need a forecast to know caution is cheap.", "source": "Mastering the Market Cycle — Howard Marks"},
  {"id": 44, "category": "Stock Trading", "text": "Warren Buffett's rule of temperament: 'Be fearful when others are greedy and greedy when others are fearful.' Simple to say, brutally hard to do at the exact moment it matters.", "source": "Berkshire Hathaway shareholder letters"},
  {"id": 45, "category": "Stock Trading", "text": "Stay inside your circle of competence. The size of the circle matters far less than knowing precisely where its edges are — most blow-ups happen just outside them.", "source": "Warren Buffett — Berkshire letters"},
  {"id": 46, "category": "Stock Trading", "text": "Phil Fisher's scuttlebutt method: talk to customers, competitors, and suppliers. The most valuable information about a company rarely sits in its own investor presentation.", "source": "Common Stocks and Uncommon Profits — Philip Fisher"},
  {"id": 47, "category": "Stock Trading", "text": "Fisher's selling rule: if you did the work properly when you bought, the time to sell an outstanding company is almost never — unless the original thesis has genuinely broken.", "source": "Common Stocks and Uncommon Profits — Philip Fisher"},
  {"id": 48, "category": "Stock Trading", "text": "Cut losses quickly and mechanically. William O'Neil's rule was 7–8% below purchase price, no exceptions — because the arithmetic of losses is cruel: a 50% loss needs a 100% gain to get back to even.", "source": "How to Make Money in Stocks — William O'Neil"},
  {"id": 49, "category": "Stock Trading", "text": "Minervini's ordering: risk comes first, always. Before asking what a trade can make, define exactly where it's wrong and what that costs. No defined exit, no trade.", "source": "Trade Like a Stock Market Wizard — Mark Minervini"},
  {"id": 50, "category": "Stock Trading", "text": "Every position needs an invalidation point decided before entry — the price or fact that proves the idea wrong. Without one, a losing trade quietly becomes a long-term investment you never chose.", "source": "Risk management practice"},
  {"id": 51, "category": "Stock Trading", "text": "Expectancy is the number that matters: your win rate times your average win, minus your loss rate times your average loss. A 40% win rate is highly profitable if winners are three times the size of losers.", "source": "Trade Your Way to Financial Freedom — Van Tharp"},
  {"id": 52, "category": "Stock Trading", "text": "Asymmetry is the whole game: hunt for trades risking one unit to plausibly make three or more. With that shape you can be wrong most of the time and still compound.", "source": "Risk/reward asymmetry — trading practice"},
  {"id": 53, "category": "Stock Trading", "text": "Bessembinder's finding: since 1926, most individual US stocks underperformed Treasury bills over their lifetimes. A tiny fraction of big winners produced nearly all net market gains. Stock picking is a search for outliers.", "source": "'Do Stocks Outperform Treasury Bills?' — Hendrik Bessembinder"},
  {"id": 54, "category": "Stock Trading", "text": "Keynes' attributed warning: markets can remain irrational longer than you can remain solvent. Being early and being wrong feel identical to your account balance.", "source": "Attributed to John Maynard Keynes"},
  {"id": 55, "category": "Stock Trading", "text": "Soros' reflexivity: prices don't just reflect fundamentals — they change them. A rising stock lets a company raise cheap capital and attract talent, partly justifying the rise. Cause and effect loop.", "source": "The Alchemy of Finance — George Soros"},
  {"id": 56, "category": "Stock Trading", "text": "The crowd is right during the trend and wrong at both ends. Fighting the middle of a trend and joining the euphoric end are the two most reliably expensive habits in markets.", "source": "Technical analysis tradition — Charles Dow onwards"},
  {"id": 57, "category": "Stock Trading", "text": "Murphy's core premise of technical analysis: price discounts everything knowable, price moves in trends, and history rhymes because human psychology doesn't change. Charts are crowd psychology made visible.", "source": "Technical Analysis of the Financial Markets — John Murphy"},
  {"id": 58, "category": "Stock Trading", "text": "Volume is conviction. A breakout on heavy volume means real commitment behind the move; the same breakout on thin volume is a rumour that hasn't been fact-checked.", "source": "Technical Analysis of the Financial Markets — John Murphy"},
  {"id": 59, "category": "Stock Trading", "text": "Volatility clusters: big moves follow big moves, quiet follows quiet. A market that has just shocked you once is statistically more likely to do it again soon — size accordingly.", "source": "Engle's ARCH research — volatility clustering"},
  {"id": 60, "category": "Stock Trading", "text": "Know whether your setup is a momentum trade or a mean-reversion trade, because they need opposite behaviour: momentum adds to strength; mean reversion fades it. Mixing the two mid-trade is how good entries become bad exits.", "source": "Quantitative trading practice"},
  {"id": 61, "category": "Stock Trading", "text": "Diversification quietly fails when you need it most: in a crash, correlations lunge towards one and everything falls together. Stress-test the portfolio against that day, not against calm markets.", "source": "Portfolio risk research — correlation breakdown"},
  {"id": 62, "category": "Stock Trading", "text": "Liquidity is a hidden position cost. A holding you can't exit at a fair price during stress isn't really the size you think it is — the door matters as much as the room.", "source": "Market microstructure — liquidity risk"},
  {"id": 63, "category": "Stock Trading", "text": "Never average down on a loser without a written thesis for why the market is wrong. 'It's cheaper now' is not a thesis — it's the same idea, twice the exposure, half the objectivity.", "source": "Risk management practice"},
  {"id": 64, "category": "Stock Trading", "text": "Match your analysis to your holding period. A daily chart opinion with a ten-minute attention span — or a scalper's nerves on a six-month thesis — is a mismatch that creates losses from nowhere.", "source": "Trading timeframe discipline"},
  {"id": 65, "category": "Stock Trading", "text": "Old market saying: there are old traders and bold traders, but very few old, bold traders. Survival is the strategy that makes every other strategy possible.", "source": "Trading proverb"},
  {"id": 66, "category": "Stock Trading", "text": "Sell down to the sleeping point. If a position keeps you up at night, the market is telling you your size is wrong — reduce until you can think again.", "source": "Old Wall Street maxim"},
  {"id": 67, "category": "Stock Trading", "text": "A catalyst turns cheap into profitable. Undervalued stocks can stay undervalued for years; ask what specific event — earnings, buyback, spin-off, new management — forces the market to reprice.", "source": "Value investing practice — catalysts"},
  {"id": 68, "category": "Stock Trading", "text": "Lynch's edge for private investors: you'll often see great products in daily life months before analysts model them. Your job is then the boring part — checking the balance sheet backs the story.", "source": "One Up on Wall Street — Peter Lynch"},
  {"id": 69, "category": "Stock Trading", "text": "Buffett's holding test: only own something you'd be comfortable holding if the market shut for ten years. It instantly filters out positions that are really just bets on other people's moods.", "source": "Warren Buffett — Berkshire letters"},
  {"id": 70, "category": "Stock Trading", "text": "Backtests flatter. Every published strategy survived; the thousands that blew up in testing are invisible. Assume live results will be worse than the backtest — then decide if it's still worth trading.", "source": "Quantitative finance — overfitting"},
  {"id": 71, "category": "Financial Advice", "text": "Wealth is what you don't see. The cars and watches are money spent — the actual wealth is the invisible pile of assets that wasn't converted into things. Judging wealth by what's visible measures the opposite.", "source": "The Psychology of Money — Morgan Housel"},
  {"id": 72, "category": "Financial Advice", "text": "Your savings rate matters more than your investment returns, especially early on. Saving 30% of income with average returns beats saving 5% with brilliant returns for decades.", "source": "The Psychology of Money — Morgan Housel"},
  {"id": 73, "category": "Financial Advice", "text": "Getting wealthy and staying wealthy are different skills. Getting wealthy takes optimism and risk; staying wealthy takes paranoia, frugality, and the humility to know some of it was luck.", "source": "The Psychology of Money — Morgan Housel"},
  {"id": 74, "category": "Financial Advice", "text": "Aim to be reasonable, not perfectly rational. A slightly suboptimal plan you'll actually stick with through a crash beats the mathematically optimal one you'll abandon at the bottom.", "source": "The Psychology of Money — Morgan Housel"},
  {"id": 75, "category": "Financial Advice", "text": "Build room for error into every plan. The most important part of a financial plan is that it survives the plan not going to plan — savings buffers, moderate leverage, low fixed costs.", "source": "The Psychology of Money — Morgan Housel"},
  {"id": 76, "category": "Financial Advice", "text": "Define your 'enough' number before the game defines it for you. Housel retells the exchange between Heller and Vonnegut at a billionaire's party: Heller had something the host could never have — enough.", "source": "The Psychology of Money — Morgan Housel"},
  {"id": 77, "category": "Financial Advice", "text": "Jack Bogle's simplification: 'Don't look for the needle in the haystack. Just buy the haystack.' Owning the whole market cheaply guarantees you hold the few big winners that drive nearly all returns.", "source": "The Little Book of Common Sense Investing — John Bogle"},
  {"id": 78, "category": "Financial Advice", "text": "Costs compound just like returns, but against you. A 2% annual fee sounds tiny; over 40 years it can consume well over a third of your final pot. Fees are the most predictable drag in investing.", "source": "The Little Book of Common Sense Investing — John Bogle"},
  {"id": 79, "category": "Financial Advice", "text": "The behaviour gap: fund investors reliably earn less than the funds they invest in, because they buy after rises and sell after falls. The biggest fee most people pay is their own timing.", "source": "The Behavior Gap — Carl Richards"},
  {"id": 80, "category": "Financial Advice", "text": "F-you money isn't about luxury. It's the pile that lets you say no — to a bad boss, a bad deal, a bad situation. Every pound saved is a small purchase of freedom.", "source": "The Simple Path to Wealth — JL Collins"},
  {"id": 81, "category": "Financial Advice", "text": "JL Collins on crashes: the market always recovers eventually, but only for people still holding. Selling in a panic converts a temporary decline into a permanent loss.", "source": "The Simple Path to Wealth — JL Collins"},
  {"id": 82, "category": "Financial Advice", "text": "Pay yourself first: the Babylonian rule of keeping at least a tenth of everything you earn before any spending. What remains gets spent regardless — so put savings at the front of the queue, automatically.", "source": "The Richest Man in Babylon — George Clason"},
  {"id": 83, "category": "Financial Advice", "text": "Clason's second law: make your gold work for you. Money sitting idle is a workforce on holiday — each pound invested becomes a little labourer earning more labourers.", "source": "The Richest Man in Babylon — George Clason"},
  {"id": 84, "category": "Financial Advice", "text": "Most actual millionaires drive ordinary cars, live in modest houses, and budget carefully. Stanley and Danko's research found high income and high spending often produce low wealth — the flash is usually financed.", "source": "The Millionaire Next Door — Stanley & Danko"},
  {"id": 85, "category": "Financial Advice", "text": "Income is not wealth. Wealth is what accumulates after spending — a surgeon spending everything is poorer, in balance-sheet terms, than a teacher who invested for thirty years.", "source": "The Millionaire Next Door — Stanley & Danko"},
  {"id": 86, "category": "Financial Advice", "text": "Automate the decision. Money moved to savings and investments on payday, before you see it, removes willpower from the system entirely. Ramit Sethi's point: systems beat discipline.", "source": "I Will Teach You to Be Rich — Ramit Sethi"},
  {"id": 87, "category": "Financial Advice", "text": "Spend extravagantly on the things you love and cut mercilessly on the things you don't. Conscious spending isn't about less — it's about deciding on purpose instead of by default.", "source": "I Will Teach You to Be Rich — Ramit Sethi"},
  {"id": 88, "category": "Financial Advice", "text": "Lifestyle inflation is the silent tax on every pay rise. If spending grows to match income automatically, a doubling of salary can leave you exactly as broke — just with nicer stuff.", "source": "Personal finance principle"},
  {"id": 89, "category": "Financial Advice", "text": "An emergency fund isn't an investment — it's insurance that pays out in options. Three to six months of expenses means a job loss or a boiler failure is a problem, not a catastrophe with interest.", "source": "Personal finance practice"},
  {"id": 90, "category": "Financial Advice", "text": "Debt has a direction. Borrowing for assets that can grow — a business, a rental property, skills — is a tool. Borrowing for consumption is renting a lifestyle at interest from your future self.", "source": "Personal finance principle"},
  {"id": 91, "category": "Financial Advice", "text": "Thoreau's accounting: the real price of a thing is the amount of life you exchange for it. A £30,000 car bought on a £15-an-hour wage costs two thousand hours of your one life.", "source": "Walden — Henry David Thoreau (paraphrased)"},
  {"id": 92, "category": "Financial Advice", "text": "Buffett's rule on risk: never risk what you have and need for what you don't have and don't need. Most financial disasters start with an unnecessary bet made from a position of comfort.", "source": "Warren Buffett — on leverage and ruin"},
  {"id": 93, "category": "Financial Advice", "text": "Missing just the handful of best days in the market historically destroys a large share of long-term returns — and those best days cluster right next to the worst ones. This is the case for staying invested.", "source": "Market timing research — time in the market"},
  {"id": 94, "category": "Financial Advice", "text": "The market's long-term average return already includes the crashes. You don't get the average by avoiding the bad years — you get it by sitting through them.", "source": "Stock market history"},
  {"id": 95, "category": "Financial Advice", "text": "Rebalancing is a machine for doing the hard thing: it mechanically sells what has risen and buys what has fallen, forcing buy-low-sell-high behaviour precisely when your emotions vote against it.", "source": "Portfolio management practice"},
  {"id": 96, "category": "Financial Advice", "text": "Cash isn't trash — it's optionality. A cash reserve is a paid-up option on every future bargain and every emergency, which is why the people with cash in a crisis end up owning the assets.", "source": "The Psychology of Money — Morgan Housel"},
  {"id": 97, "category": "Financial Advice", "text": "Negotiating your salary is one of the highest-return financial moves available. A single £5,000 raise compounds through every future raise, pension contribution, and job offer for decades.", "source": "Personal finance — career capital"},
  {"id": 98, "category": "Financial Advice", "text": "Track your net worth, not your income. It's the one number that summarises every financial decision you've made, and what gets measured monthly tends to quietly improve.", "source": "Personal finance practice"},
  {"id": 99, "category": "Financial Advice", "text": "Buy the house as a home, not an investment. After mortgage interest, maintenance, insurance, and transaction costs, most owner-occupied housing returns far less than owners believe — its real dividend is stability.", "source": "Housing economics research"},
  {"id": 100, "category": "Financial Advice", "text": "Frugal is not cheap. Cheap buys the £20 boots five times; frugal buys the £80 boots once. Think in cost per use, not price per purchase.", "source": "Personal finance — cost per use"},
  {"id": 101, "category": "Financial Advice", "text": "Insurance exists for the losses you cannot absorb, not the ones you can. Self-insure the small stuff with your emergency fund; transfer only the catastrophic risks. Paying to insure trivia is a guaranteed slow leak.", "source": "Risk management principle"},
  {"id": 102, "category": "Financial Advice", "text": "Rich is current income; wealthy is unspent assets and the freedom they buy. Plenty of rich people are one missed month from trouble. The goal is wealthy — and it's mostly invisible.", "source": "The Psychology of Money — Morgan Housel"},
  {"id": 103, "category": "Life Advice", "text": "You don't rise to the level of your goals; you fall to the level of your systems. Goals set direction, but the daily system — what you actually do on an average Tuesday — determines the result.", "source": "Atomic Habits — James Clear"},
  {"id": 104, "category": "Life Advice", "text": "Getting 1% better every day compounds to roughly 37 times better over a year. The maths: 1.01 multiplied by itself 365 times is about 37.8. Tiny gains feel like nothing daily and everything yearly.", "source": "Atomic Habits — James Clear"},
  {"id": 105, "category": "Life Advice", "text": "Change identity, not just behaviour. 'I'm trying to quit smoking' loses to 'I'm not a smoker.' Every action is a vote for the type of person you believe you are.", "source": "Atomic Habits — James Clear"},
  {"id": 106, "category": "Life Advice", "text": "Design the environment instead of relying on willpower. Put the guitar on a stand in the living room; put the phone in another room. You become what your surroundings make easy.", "source": "Atomic Habits — James Clear"},
  {"id": 107, "category": "Life Advice", "text": "The two-minute rule: scale any new habit down to something that takes two minutes. 'Read before bed' becomes 'read one page.' You're not building the habit yet — you're building the identity of someone who shows up.", "source": "Atomic Habits — James Clear"},
  {"id": 108, "category": "Life Advice", "text": "The plateau of latent potential: habits appear to do nothing for months, then results arrive all at once — like ice melting only when the room finally crosses zero. Most people quit in the valley just before the breakthrough.", "source": "Atomic Habits — James Clear"},
  {"id": 109, "category": "Life Advice", "text": "Begin with the end in mind. Covey's exercise: write what you'd want said at your own funeral, then check whether your calendar this week has anything to do with it.", "source": "The 7 Habits of Highly Effective People — Stephen Covey"},
  {"id": 110, "category": "Life Advice", "text": "Work your circle of influence, not your circle of concern. Energy spent on things you can't affect — the news, other people's choices — shrinks your actual power. Energy spent where you have leverage expands it.", "source": "The 7 Habits of Highly Effective People — Stephen Covey"},
  {"id": 111, "category": "Life Advice", "text": "Schedule the big rocks first. If the week fills with gravel — email, errands, other people's urgencies — the important things never fit. Put them in the calendar before anything else gets a slot.", "source": "First Things First — Stephen Covey"},
  {"id": 112, "category": "Life Advice", "text": "Seek first to understand, then to be understood. Most people don't listen with the intent to understand; they listen with the intent to reply. Reversing that order transforms almost every relationship.", "source": "The 7 Habits of Highly Effective People — Stephen Covey"},
  {"id": 113, "category": "Life Advice", "text": "Sharpen the saw: the producer who never maintains the machine — body, mind, relationships — gets slower every year while feeling busier. Renewal isn't a break from the work; it's what makes the work possible.", "source": "The 7 Habits of Highly Effective People — Stephen Covey"},
  {"id": 114, "category": "Life Advice", "text": "Deep work — long, undistracted focus on hard things — is becoming rarer exactly as it becomes more valuable. The ability to concentrate for hours is now a career-defining skill you can train like a muscle.", "source": "Deep Work — Cal Newport"},
  {"id": 115, "category": "Life Advice", "text": "Newport's rule for technology: don't ask whether a tool has any benefit — almost everything does. Ask whether it's one of the best uses of your limited attention. Most apps fail that test instantly.", "source": "Digital Minimalism — Cal Newport"},
  {"id": 116, "category": "Life Advice", "text": "If it isn't a clear yes, it's a no. McKeown's essentialist filter: apply a 90% rule to opportunities — anything scoring below 9 out of 10 gets declined, freeing you for the few things that matter.", "source": "Essentialism — Greg McKeown"},
  {"id": 117, "category": "Life Advice", "text": "When you don't prioritise your life, someone else will. Every unguarded hour gets claimed by whoever asks loudest — usually for their priorities, not yours.", "source": "Essentialism — Greg McKeown"},
  {"id": 118, "category": "Life Advice", "text": "Frankl's discovery in the camps: everything can be taken from a person except the last freedom — the ability to choose one's attitude in any given set of circumstances. Between what happens and how you respond, there is a choice.", "source": "Man's Search for Meaning — Viktor Frankl"},
  {"id": 119, "category": "Life Advice", "text": "Don't aim at happiness directly — it must ensue as the side effect of dedication to something bigger than yourself. Frankl: the more you chase it, the more it recedes.", "source": "Man's Search for Meaning — Viktor Frankl"},
  {"id": 120, "category": "Life Advice", "text": "Compare yourself to who you were yesterday, not to who someone else is today. The only race where the finish line is honest is the one against your former self.", "source": "12 Rules for Life — Jordan Peterson"},
  {"id": 121, "category": "Life Advice", "text": "The top regret of the dying, recorded by a palliative nurse: 'I wish I'd had the courage to live a life true to myself, not the life others expected of me.' Second on the list: working too much.", "source": "The Top Five Regrets of the Dying — Bronnie Ware"},
  {"id": 122, "category": "Life Advice", "text": "You get about four thousand weeks. Burkeman's point isn't to optimise them all — it's that accepting you'll never do everything is what finally lets you choose something and commit.", "source": "Four Thousand Weeks — Oliver Burkeman"},
  {"id": 123, "category": "Life Advice", "text": "Pay yourself first with time, not just money. If the important-but-not-urgent things — writing, training, family — only get whatever hours are left over, there will never be any left over.", "source": "Four Thousand Weeks — Oliver Burkeman"},
  {"id": 124, "category": "Life Advice", "text": "The eighty-plus-year Harvard study of adult development reached a blunt conclusion: the strongest predictor of health and happiness in old age wasn't wealth or fame — it was the quality of close relationships at fifty.", "source": "The Good Life — Waldinger & Schulz"},
  {"id": 125, "category": "Life Advice", "text": "Relationships need what Waldinger calls social fitness — active maintenance, like physical fitness. Friendships don't end in fallings-out; they starve quietly from neglect. An unprompted message is a workout.", "source": "The Good Life — Waldinger & Schulz"},
  {"id": 126, "category": "Life Advice", "text": "If you can't explain it simply, you don't understand it yet. Feynman's technique: teach the idea to an imaginary twelve-year-old, notice exactly where you get stuck, and that's where your understanding has a hole.", "source": "Richard Feynman's learning method"},
  {"id": 127, "category": "Life Advice", "text": "Invert, always invert. Instead of asking how to succeed, ask what would guarantee failure — then avoid those things. Munger built a career on the observation that avoiding stupidity is easier than seeking brilliance.", "source": "Poor Charlie's Almanack — Charlie Munger"},
  {"id": 128, "category": "Life Advice", "text": "Eat the frog: do the hardest, most avoided task first thing in the morning. Everything after it feels lighter, and the day's willpower gets spent on what matters instead of on dread.", "source": "Eat That Frog — Brian Tracy"},
  {"id": 129, "category": "Life Advice", "text": "Consistency beats intensity. The person who trains three times a week for five years beats the person who trains daily for three weeks, quits, and restarts — in fitness, money, skills, everything.", "source": "Habit research — frequency over heroics"},
  {"id": 130, "category": "Life Advice", "text": "Manage your energy, not just your time. An hour when you're sharp is worth three when you're depleted — so match your hardest work to your best hours and treat recovery as part of the job.", "source": "The Power of Full Engagement — Loehr & Schwartz"},
  {"id": 131, "category": "Life Advice", "text": "Write things down. An idea in your head is a browser tab draining battery; an idea on paper is stored and searchable. Your mind is for having ideas, not holding them.", "source": "Getting Things Done — David Allen"},
  {"id": 132, "category": "Life Advice", "text": "For big decisions, run the 10/10/10 test: how will I feel about this in ten minutes, ten months, and ten years? It separates what's merely uncomfortable now from what actually matters later.", "source": "10-10-10 — Suzy Welch"},
  {"id": 133, "category": "Life Advice", "text": "Boredom is a feature, not a bug. The itch you feel in a queue without your phone is where daydreaming, ideas, and processing used to happen. Leave some gaps unfilled on purpose.", "source": "Bored and Brilliant — Manoush Zomorodi"},
  {"id": 134, "category": "Life Advice", "text": "A daily walk is the most underrated tool in existence: it counts as exercise, thinking time, stress processing, and creativity practice simultaneously. Darwin structured his working day around three of them.", "source": "Daily rituals of thinkers — the walking habit"},
  {"id": 135, "category": "Stress", "text": "Your stress response evolved for sprinting from lions — a burst of fuel, then it's over. Sapolsky's point: humans are unique in switching it on with pure thought and leaving it running for months. Chronic activation is the damage.", "source": "Why Zebras Don't Get Ulcers — Robert Sapolsky"},
  {"id": 136, "category": "Stress", "text": "Two things reliably shrink a stress response: predictability and a sense of control. Even a small ritual you control — a routine, a checklist, a planned break — measurably lowers the biological cost of a hard situation.", "source": "Why Zebras Don't Get Ulcers — Robert Sapolsky"},
  {"id": 137, "category": "Stress", "text": "Dealing with the stressor doesn't complete the stress cycle — the body needs its own signal that it's safe. The Nagoskis' evidence-backed closers: movement, deep breathing, laughter, crying, affection, creativity.", "source": "Burnout — Emily & Amelia Nagoski"},
  {"id": 138, "category": "Stress", "text": "The fastest known way to calm your nervous system in real time: the physiological sigh — two quick inhales through the nose, then one long slow exhale through the mouth. One to three of them measurably drops arousal.", "source": "Stanford research — Huberman & Spiegel"},
  {"id": 139, "category": "Stress", "text": "Your exhale is a brake pedal. Making the out-breath longer than the in-breath activates the parasympathetic system directly — it's the one part of the calm response you can steer by hand.", "source": "Breath — James Nestor"},
  {"id": 140, "category": "Stress", "text": "Nestor's optimal breathing rhythm from the research: about 5.5-second inhales and 5.5-second exhales — roughly five and a half breaths a minute. Slow nasal breathing changes blood chemistry, heart rate, and mood.", "source": "Breath — James Nestor"},
  {"id": 141, "category": "Stress", "text": "Name it to tame it: putting a feeling into words — 'this is anxiety about tomorrow's meeting' — reduces amygdala activity on brain scans. Labelling an emotion is the first step of regulating it.", "source": "Affect labelling research — Lieberman; phrase from Dan Siegel"},
  {"id": 142, "category": "Stress", "text": "Rumination is rehearsing a threat over and over without the relief of it ending. Your body reacts to each mental replay as if it were real — you can have one bad meeting and experience it forty times.", "source": "Stress psychology — rumination"},
  {"id": 143, "category": "Stress", "text": "Schedule your worry. Give anxious thoughts a fixed 15-minute daily slot and postpone them to it when they intrude. Most lose their urgency before their appointment — and the rest get handled at a time you chose.", "source": "Cognitive behavioural technique — stimulus control"},
  {"id": 144, "category": "Stress", "text": "Ask of any worry: 'Is this thought useful right now?' Not whether it's true — whether it's useful. If it doesn't change what you'll do in the next hour, it's just cortisol with no job.", "source": "Acceptance and commitment therapy — workability"},
  {"id": 145, "category": "Stress", "text": "Your belief about stress changes what stress does. Crum's studies: people taught that stress responses are the body rising to a challenge showed healthier physiology under pressure than those taught stress is harmful.", "source": "The Upside of Stress — Kelly McGonigal / Alia Crum research"},
  {"id": 146, "category": "Stress", "text": "Challenge versus threat: the same racing heart before a big moment can be read as 'I'm ready' or 'I'm in danger.' Reappraising arousal as readiness measurably improves performance — the body follows the interpretation.", "source": "Stress appraisal research — Jamieson"},
  {"id": 147, "category": "Stress", "text": "Social support is a biological buffer, not a nicety: talking to someone you trust after a stressor measurably blunts the cortisol response. Isolation makes the same event cost more.", "source": "Why Zebras Don't Get Ulcers — Robert Sapolsky"},
  {"id": 148, "category": "Stress", "text": "Twenty minutes in a green space lowers cortisol — the effect shows up even without exercise. Attention restoration theory: nature demands nothing of you, which is exactly what a depleted mind needs.", "source": "Attention restoration research — Kaplan; nature-dose studies"},
  {"id": 149, "category": "Stress", "text": "Expressive writing works: fifteen to twenty minutes writing honestly about a stressful experience, over a few sessions, improved measurable health outcomes in Pennebaker's studies. Translating chaos into sentences is processing.", "source": "Expressive writing research — James Pennebaker"},
  {"id": 150, "category": "Stress", "text": "Sleep deprivation turns the amygdala's volume up: after a short night, the brain's threat detector over-reacts by as much as 60% in imaging studies. Half of 'everything is going wrong' is sometimes just tiredness.", "source": "Why We Sleep — Matthew Walker"},
  {"id": 151, "category": "Stress", "text": "Alcohol borrows calm from tomorrow. It sedates you tonight, then fragments sleep and spikes anxiety as it leaves — the 3am wake-up and next-day dread are part of the price, not a coincidence.", "source": "Sleep and alcohol research"},
  {"id": 152, "category": "Stress", "text": "Do a body audit: unclench the jaw, drop the shoulders, unfurrow the brow. Tension held in the body feeds back into the brain as evidence of threat — releasing the muscle releases some of the message.", "source": "Progressive muscle relaxation — Jacobson tradition"},
  {"id": 153, "category": "Stress", "text": "Progressive muscle relaxation: tense each muscle group hard for five seconds, then release, moving through the body. The contrast teaches your nervous system what 'released' actually feels like — most people have forgotten.", "source": "Edmund Jacobson's method"},
  {"id": 154, "category": "Stress", "text": "Micro-breaks beat marathon recovery. Brief pauses every hour — stand, look out a window, breathe — keep stress from compounding through the day. You can't cram a week of recovery into a Sunday.", "source": "Occupational recovery research"},
  {"id": 155, "category": "Stress", "text": "Multitasking is a stress generator: every switch leaves attention residue and adds a small cost in cortisol and errors. Single-tasking the same workload feels calmer because, chemically, it is.", "source": "Task-switching research — attention residue (Leroy)"},
  {"id": 156, "category": "Stress", "text": "The news is a stress subscription billed to your nervous system. Constant exposure to distant crises you can't influence produces real cortisol for zero actionable benefit. Check twice a day; live in between.", "source": "Media exposure and stress research"},
  {"id": 157, "category": "Stress", "text": "Caffeine stacks on top of stress — it raises cortisol and heart rate, then blocks the sleepiness signal for hours (its half-life is five to six hours). On a hard day, the second afternoon coffee is often paid for at 2am.", "source": "Caffeine pharmacology research"},
  {"id": 158, "category": "Stress", "text": "A hot bath or shower 60–90 minutes before bed helps you fall asleep faster — the after-cooling drops your core temperature, which is one of the body's main sleep triggers.", "source": "Passive body heating studies"},
  {"id": 159, "category": "Stress", "text": "Laughter is a legitimate intervention: it completes the stress cycle, drops stress hormones, and bonds you to whoever you're laughing with. It's not a distraction from coping — it is coping.", "source": "Burnout — Emily & Amelia Nagoski"},
  {"id": 160, "category": "Stress", "text": "Slow music slows you. Tempo entrains heart rate and breathing — tracks around 60 beats per minute measurably reduce physiological arousal. You've been using this instinctively; now use it deliberately.", "source": "Music and autonomic response research"},
  {"id": 161, "category": "Stress", "text": "Cortisol naturally peaks shortly after waking and falls through the day. Fighting that rhythm — screens and stimulation at midnight, big decisions when depleted — is stress you're manufacturing against your own biology.", "source": "Circadian cortisol research"},
  {"id": 162, "category": "Stress", "text": "When overwhelmed, shrink the timeframe. You don't have to get through the month, the week, or even the day — just the next hour. Competence returns at small scales, and hours add up to the month anyway.", "source": "Crisis psychology — chunking"},
  {"id": 163, "category": "Stress", "text": "Maté's warning: the body says no when you won't. People who chronically suppress their own needs to keep everyone else happy carry the cost physically. Saying no to others is sometimes saying yes to your health.", "source": "When the Body Says No — Gabor Maté"},
  {"id": 164, "category": "Stress", "text": "Stress plus exercise is not more stress. Physical exertion is the outlet the stress response was built for — it burns off the mobilised fuel and signals the emergency is over. A hard day is an argument for the gym, not against it.", "source": "Why Zebras Don't Get Ulcers — Robert Sapolsky"},
  {"id": 165, "category": "Overcoming Trauma", "text": "Trauma isn't stored as a story — it's stored in the body: posture, breath, startle responses, sensations. That's van der Kolk's core finding, and why healing usually needs the body involved, not just talk.", "source": "The Body Keeps the Score — Bessel van der Kolk"},
  {"id": 166, "category": "Overcoming Trauma", "text": "Healing works both top-down and bottom-up: talking, understanding, and meaning-making from above; breath, movement, and rhythm from below. The people who recover best usually use both channels.", "source": "The Body Keeps the Score — Bessel van der Kolk"},
  {"id": 167, "category": "Overcoming Trauma", "text": "Rhythm regulates. Van der Kolk found drumming, dancing, singing, and even walking in step help traumatised nervous systems re-organise — rhythm is one of the oldest safety signals the body knows.", "source": "The Body Keeps the Score — Bessel van der Kolk"},
  {"id": 168, "category": "Overcoming Trauma", "text": "Perry's reframe changes everything: not 'what's wrong with you?' but 'what happened to you?' Behaviour that looks broken is usually an adaptation that made perfect sense in the environment where it was learned.", "source": "What Happened to You? — Bruce Perry & Oprah Winfrey"},
  {"id": 169, "category": "Overcoming Trauma", "text": "The sequence of engagement: regulate, relate, then reason. A dysregulated brain cannot be reached by logic — calm the body first, connect second, and only then does reasoning become possible. This applies to yourself too.", "source": "What Happened to You? — Bruce Perry"},
  {"id": 170, "category": "Overcoming Trauma", "text": "Resilience is built by moderate, predictable, controllable doses of stress with recovery in between — Perry compares it to strength training for the nervous system. It's the unpredictable, uncontrollable kind that wounds.", "source": "What Happened to You? — Bruce Perry"},
  {"id": 171, "category": "Overcoming Trauma", "text": "Maté's definition: trauma is not what happens to you — it's what happens inside you as a result. Two people can live the same event; the wound is in the meaning and the disconnection, which means it can heal.", "source": "The Myth of Normal — Gabor Maté"},
  {"id": 172, "category": "Overcoming Trauma", "text": "Maté on addiction: don't ask why the addiction, ask why the pain. Compulsions of every kind — substances, work, screens — usually began as attempted solutions to suffering. Treat the pain and the solution loses its job.", "source": "In the Realm of Hungry Ghosts — Gabor Maté"},
  {"id": 173, "category": "Overcoming Trauma", "text": "Levine's insight from watching prey animals: trauma is the energy of a survival response that never got to complete. Wild animals shake it off and move on; humans hold it in. Completion — often through the body — is the way out.", "source": "Waking the Tiger — Peter Levine"},
  {"id": 174, "category": "Overcoming Trauma", "text": "Titration: approach difficult material in small, tolerable doses, not all at once. Levine's method touches the edge of the hard thing, returns to safety, and repeats. Flooding overwhelms; sips heal.", "source": "Somatic experiencing — Peter Levine"},
  {"id": 175, "category": "Overcoming Trauma", "text": "Pendulation: deliberately swing attention between a difficult sensation and a place in your body that feels okay. The nervous system learns that distress is a state it can enter and leave — not a place it lives.", "source": "Somatic experiencing — Peter Levine"},
  {"id": 176, "category": "Overcoming Trauma", "text": "The window of tolerance: the zone where you can feel things without being hijacked by them. Above it is overwhelm, below it is shutdown. Healing widens the window — mostly through safety, practice, and co-regulation.", "source": "Dan Siegel's window of tolerance"},
  {"id": 177, "category": "Overcoming Trauma", "text": "Grounding through the senses interrupts a spiral: name five things you can see, four you can hear, three you can touch, two you can smell, one you can taste. It pulls the brain from remembered danger to present reality.", "source": "Grounding techniques — trauma therapy practice"},
  {"id": 178, "category": "Overcoming Trauma", "text": "An emotional flashback, in Pete Walker's terms, is suddenly feeling the helplessness or shame of the past without any visual memory attached — it just feels like now. Recognising 'this is a flashback' is itself the first intervention.", "source": "Complex PTSD: From Surviving to Thriving — Pete Walker"},
  {"id": 179, "category": "Overcoming Trauma", "text": "Walker's work on the inner critic: a harsh internal voice often formed as protection — attack yourself first and maybe others won't. Thanking it for its service and retiring it is a genuine, practised skill.", "source": "Complex PTSD — Pete Walker"},
  {"id": 180, "category": "Overcoming Trauma", "text": "Speak to yourself as you would to the child you were. Self-compassion isn't indulgence — in Neff's research it outperforms self-criticism on every measure of motivation, resilience, and recovery.", "source": "Self-Compassion — Kristin Neff"},
  {"id": 181, "category": "Overcoming Trauma", "text": "Safe relationships are the active ingredient. Nervous systems calibrate against other nervous systems — co-regulation with steady, trustworthy people is how a body relearns that the emergency is over.", "source": "The Body Keeps the Score — attachment and co-regulation"},
  {"id": 182, "category": "Overcoming Trauma", "text": "Post-traumatic growth is real and common: after profound difficulty, many people report deeper relationships, clearer priorities, and strength they didn't know they had. It never erases the pain — it grows beside it.", "source": "Post-traumatic growth research — Tedeschi & Calhoun"},
  {"id": 183, "category": "Overcoming Trauma", "text": "Making a coherent story of what happened — with a beginning, middle, and end — measurably reduces its power. Fragmented memory intrudes; narrative memory is filed. Writing and therapy both work partly by building the file.", "source": "Narrative processing research — Pennebaker tradition"},
  {"id": 184, "category": "Overcoming Trauma", "text": "The goal isn't forgetting. It's the memory losing its charge — becoming something that happened to you rather than something that is happening to you. That shift is what recovery actually feels like.", "source": "Trauma therapy — memory reconsolidation"},
  {"id": 185, "category": "Overcoming Trauma", "text": "Self-blame after harm is often the mind's bid for control: 'if it was my fault, I could have prevented it, so the world is still predictable.' Seeing the mechanism loosens its grip.", "source": "Trauma psychology — the control function of self-blame"},
  {"id": 186, "category": "Overcoming Trauma", "text": "Triggers are information. A big reaction to a small event is a map reference — it marks where old material lives. Curiosity about the reaction ('what did that touch?') turns an ambush into data.", "source": "Trauma-informed practice"},
  {"id": 187, "category": "Overcoming Trauma", "text": "Boundaries are a skill trauma often erased. Every kept boundary — a no that holds, a limit that's respected — is direct evidence to your nervous system that you are no longer powerless.", "source": "Complex PTSD recovery — Pete Walker tradition"},
  {"id": 188, "category": "Overcoming Trauma", "text": "Small, predictable routines rebuild safety from the ground up: same wake time, a morning ritual, regular meals. To a dysregulated system, boring is medicinal — predictability is proof the world can be trusted again.", "source": "Trauma recovery — rhythm and routine (Perry)"},
  {"id": 189, "category": "Overcoming Trauma", "text": "The strategies that saved you may now be the ones to retire. Hypervigilance, people-pleasing, numbing — they were intelligent responses to a dangerous time. Honour them, then ask if the danger is still here.", "source": "Trauma recovery — adaptive strategies outliving their use"},
  {"id": 190, "category": "Overcoming Trauma", "text": "Healing is not linear. Progress looks like a spiral: the same material returns at higher levels with more capacity each time. A hard week after ten good ones is a revisit, not a relapse.", "source": "Trauma recovery — the spiral model"},
  {"id": 191, "category": "Overcoming Trauma", "text": "Effective, well-studied therapies exist — trauma-focused CBT and EMDR among them — with strong evidence behind them. Getting help isn't a failure of self-reliance; it's using the best tools available for a hard job.", "source": "Trauma treatment research — NICE guidance"},
  {"id": 192, "category": "Overcoming Trauma", "text": "Yoga performed surprisingly well in van der Kolk's trauma studies — in one trial rivalling established treatments. The mechanism: learning to inhabit and tolerate your own bodily sensations again, breath by breath.", "source": "The Body Keeps the Score — Bessel van der Kolk"},
  {"id": 193, "category": "Perspective", "text": "Rosling's data: over the last two centuries, the share of humanity in extreme poverty has collapsed, child mortality has plunged, and literacy has soared. Things can be bad and getting better at the same time — hold both.", "source": "Factfulness — Hans Rosling"},
  {"id": 194, "category": "Perspective", "text": "The negativity instinct: news reports events, not trends — and disasters are events while progress is a trend. A million children not dying of measles this year is true, enormous, and will never be a headline.", "source": "Factfulness — Hans Rosling"},
  {"id": 195, "category": "Perspective", "text": "The gap instinct: we imagine 'the West and the rest,' but the two-humped world of rich and poor vanished decades ago. Most of humanity now lives in the middle — the gap you picture is mostly a memory.", "source": "Factfulness — Hans Rosling"},
  {"id": 196, "category": "Perspective", "text": "Beware straight lines. Rosling: almost nothing in the world grows in a straight line forever — trends bend, saturate, and reverse. The confident forecast that just extends the recent past is usually the wrong one.", "source": "Factfulness — Hans Rosling"},
  {"id": 197, "category": "Perspective", "text": "Money, companies, nations, and laws are shared fictions — real only because millions of strangers agree to act as if they are. Harari's point: this collective imagination is humanity's superpower and its operating system.", "source": "Sapiens — Yuval Noah Harari"},
  {"id": 198, "category": "Perspective", "text": "The impact bias: we drastically overestimate how long both triumphs and disasters will affect our happiness. Gilbert's research shows people return towards baseline far faster than they predict — after lottery wins and losses alike.", "source": "Stumbling on Happiness — Daniel Gilbert"},
  {"id": 199, "category": "Perspective", "text": "The end-of-history illusion: at every age, people report having changed enormously in the past decade but expect to change little in the next. You are currently as much a work in progress as you have ever been.", "source": "End-of-history illusion research — Quoidbach, Gilbert, Wilson"},
  {"id": 200, "category": "Perspective", "text": "Hedonic adaptation: the new car, house, or salary becomes the invisible baseline within months, and wanting resets to the next thing. The treadmill can't be escaped by running faster — only by noticing you're on it.", "source": "Hedonic adaptation research — Brickman & Campbell"},
  {"id": 201, "category": "Perspective", "text": "The turkey problem: a turkey is fed daily for a thousand days, each day increasing its statistical confidence that humans are benevolent — right up until the week before Christmas. Past stability is not proof of future safety.", "source": "The Black Swan — Nassim Taleb"},
  {"id": 202, "category": "Perspective", "text": "In WWII, analysts wanted to armour bombers where returning planes showed bullet holes. Abraham Wald reversed it: armour where the holes aren't — planes hit there never made it back. Always ask what evidence is missing.", "source": "Survivorship bias — Abraham Wald's bomber analysis"},
  {"id": 203, "category": "Perspective", "text": "The map is not the territory. Every model, plan, and belief is a simplification of reality, not reality itself — useful right up until you forget the difference and defend the map against the ground.", "source": "Alfred Korzybski"},
  {"id": 204, "category": "Perspective", "text": "David Foster Wallace's fish story: two young fish meet an older one who asks, 'How's the water?' They swim on, then one asks, 'What the hell is water?' The most important realities are the ones too obvious to see.", "source": "This Is Water — David Foster Wallace"},
  {"id": 205, "category": "Perspective", "text": "Wallace's deeper point: your default setting is to experience everything as centred on you. Real freedom is the learned ability to choose what to notice and how to construe it — especially in queues, traffic, and tedium.", "source": "This Is Water — David Foster Wallace"},
  {"id": 206, "category": "Perspective", "text": "Sonder: the realisation that every passerby is living a life as vivid and complex as your own — full of ambitions, worries, and inherited craziness — in which you appear only as an extra in the background.", "source": "The Dictionary of Obscure Sorrows — John Koenig"},
  {"id": 207, "category": "Perspective", "text": "The fundamental attribution error: we explain our own failures by circumstances and other people's by character. He cut you off because he's an idiot; you cut someone off because you were late. Flip it deliberately.", "source": "Social psychology — Ross's attribution research"},
  {"id": 208, "category": "Perspective", "text": "Stories beat statistics in your head, and that's a bug. One vivid anecdote outweighs a base rate covering ten thousand cases. When judging risk or opportunity, ask for the denominator, not the drama.", "source": "Base-rate neglect — Kahneman & Tversky"},
  {"id": 209, "category": "Perspective", "text": "The Stockdale Paradox: Admiral Stockdale survived years as a POW by holding two things at once — absolute faith he would prevail in the end, and brutal honesty about the current facts. The optimists who set rescue deadlines broke.", "source": "Good to Great — Jim Collins, on James Stockdale"},
  {"id": 210, "category": "Perspective", "text": "Success is partly luck, and admitting it makes you wiser, not weaker. Frank's research: seeing luck's role makes people more grateful, more generous, and better at building the systems that create more of it.", "source": "Success and Luck — Robert Frank"},
  {"id": 211, "category": "Perspective", "text": "The 100-year test: almost nothing that dominates today's headlines will matter in a century, and the things that will — how you treated people, what you built, who you raised — rarely trend. Allocate attention accordingly.", "source": "Long-view thinking"},
  {"id": 212, "category": "Perspective", "text": "Your future self is a stranger you're making decisions for. Hershfield's brain scans: thinking about yourself in twenty years activates the same regions as thinking about another person. Most bad long-term choices are just bad treatment of that stranger.", "source": "Hal Hershfield's future-self research"},
  {"id": 213, "category": "Perspective", "text": "Beginner's mind: in the beginner's mind there are many possibilities; in the expert's mind there are few. Expertise builds efficient ruts — deliberately asking 'what if I knew nothing?' is how you climb out of them.", "source": "Zen Mind, Beginner's Mind — Shunryu Suzuki"},
  {"id": 214, "category": "Perspective", "text": "The obstacle is the way. The Stoic move Holiday revived: within every impediment is the raw material of the response — the setback contains the training, the rejection contains the redirect. What blocks the path becomes the path.", "source": "The Obstacle Is the Way — Ryan Holiday"},
  {"id": 215, "category": "Perspective", "text": "Practise downward counterfactuals: instead of comparing your life to the best imaginable version, occasionally compare it to how easily it could be worse. Gratitude generated this way is fast, honest, and measurable in mood studies.", "source": "Counterfactual thinking research"},
  {"id": 216, "category": "Perspective", "text": "Reading is borrowing other people's eyes. A book is decades of someone's hardest-won experience compressed into hours — the cheapest perspective transplant ever invented.", "source": "The case for reading"},
  {"id": 217, "category": "Perspective", "text": "Popper's line between science and belief: a claim is only meaningful if something could prove it wrong. Ask of your own convictions, 'What evidence would change my mind?' If the answer is nothing, it's not a belief — it's an identity.", "source": "Karl Popper — falsifiability"},
  {"id": 218, "category": "Perspective", "text": "The overview effect: astronauts who see Earth from space consistently report the same shift — borders vanish, the atmosphere looks impossibly thin, and every argument on the surface seems to shrink. You can borrow the view without the rocket.", "source": "The Overview Effect — Frank White"},
  {"id": 219, "category": "Perspective", "text": "Deathbed logic works in advance. Bronnie Ware's dying patients could see with perfect clarity what mattered — the trick is to borrow that clarity now, while the schedule can still be changed.", "source": "The Top Five Regrets of the Dying — Bronnie Ware"},
  {"id": 220, "category": "Perspective", "text": "Ask 'compared to what?' of every complaint and every fear. The slow commute compared to what — walking? The risky change compared to what — the guaranteed cost of staying put? Judgements without comparators are just moods.", "source": "Decision analysis — reference points"},
  {"id": 221, "category": "Perspective", "text": "Chesterton's fence: before removing a rule or tradition whose purpose you can't see, first find out why it was put there. Reformers who clear fences without understanding them keep meeting whatever the fence was holding back.", "source": "G.K. Chesterton — The Thing"},
  {"id": 222, "category": "Perspective", "text": "Consider the opposite. The single most effective debiasing technique in the research is embarrassingly simple: before finalising a judgement, genuinely ask 'what are the strongest reasons I might be wrong?' — and write them down.", "source": "Debiasing research — Lord, Lepper & Preston"},
  {"id": 223, "category": "Philosophy", "text": "Epictetus' dichotomy of control: some things are up to us — our judgements, intentions, and responses — and everything else is not. Peace comes from putting all your effort into the first category and none into the second.", "source": "Enchiridion — Epictetus"},
  {"id": 224, "category": "Philosophy", "text": "People are disturbed not by events, but by their opinions about events. Epictetus' claim is testable: the same delay, insult, or loss lands completely differently on different people. The variable is the judgement.", "source": "Enchiridion — Epictetus"},
  {"id": 225, "category": "Philosophy", "text": "Premeditatio malorum: the Stoics deliberately rehearsed setbacks in advance — the delay, the loss, the criticism. Not pessimism, but inoculation: nothing lands as hard when it arrives already imagined.", "source": "A Guide to the Good Life — William Irvine, on Stoic practice"},
  {"id": 226, "category": "Philosophy", "text": "Negative visualisation: spend a moment imagining life without something you have — the person, the home, the health. Irvine argues this is the Stoics' cure for hedonic adaptation: you re-experience having it for the first time.", "source": "A Guide to the Good Life — William Irvine"},
  {"id": 227, "category": "Philosophy", "text": "Memento mori — remember you will die — wasn't morbid to the ancients; it was a prioritisation tool. Nothing clarifies whether today's task matters like remembering the number of todays is finite.", "source": "Stoic practice — memento mori"},
  {"id": 228, "category": "Philosophy", "text": "Amor fati: Nietzsche's formula for greatness — not merely to bear what happens, but to love it. To want nothing to be different, backward or forward, and to make of what occurs the material of your life.", "source": "Ecce Homo — Friedrich Nietzsche"},
  {"id": 229, "category": "Philosophy", "text": "Nietzsche's eternal recurrence as a test: if you had to live this exact life, unchanged, infinitely many times — would that thought crush you or crown you? Arrange your days so the answer moves towards the second.", "source": "The Gay Science — Friedrich Nietzsche"},
  {"id": 230, "category": "Philosophy", "text": "The view from above: Marcus Aurelius practised imagining human affairs from a great height — armies, markets, weddings, funerals, all tiny and repeating. From up there, today's crisis regains its true size.", "source": "Meditations — Marcus Aurelius"},
  {"id": 231, "category": "Philosophy", "text": "Marcus' morning preparation: expect to meet the meddling, the ungrateful, and the arrogant today — they act from ignorance of good and evil, and none of them can actually harm your character without your cooperation.", "source": "Meditations — Marcus Aurelius"},
  {"id": 232, "category": "Philosophy", "text": "The Stoics sorted everything outside virtue — money, health, reputation — as 'preferred indifferents': worth pursuing, never worth trading your character for. A useful audit: what have you been treating as more than preferred?", "source": "Stoic ethics — preferred indifferents"},
  {"id": 233, "category": "Philosophy", "text": "Seneca on time: we're not given a short life, we make it short — protecting our property fiercely while letting anyone waste our hours. People are frugal with money and spendthrifts with the one thing that can't be replaced.", "source": "On the Shortness of Life — Seneca"},
  {"id": 234, "category": "Philosophy", "text": "Seneca's practice of voluntary discomfort: set aside days to eat simply and live rough, asking 'is this what I feared?' Rehearsing the worst case shrinks it — and shrinks the anxiety spent avoiding it.", "source": "Letters from a Stoic — Seneca"},
  {"id": 235, "category": "Philosophy", "text": "Epicurus divided desires: natural and necessary (food, shelter, friendship), natural but unnecessary (luxury versions of those), and empty (fame, unlimited wealth). Suffering, he argued, comes almost entirely from the third kind.", "source": "Epicurus — letter to Menoeceus"},
  {"id": 236, "category": "Philosophy", "text": "Epicurus on death: where death is, we are not; where we are, death is not. The two never meet — so the fear of being dead is a fear of something no one will ever experience.", "source": "Epicurus — letter to Menoeceus"},
  {"id": 237, "category": "Philosophy", "text": "The Buddha's second arrow: the first arrow is the pain itself — unavoidable. The second is your resistance, story, and self-blame about the pain — optional. Most suffering is the second arrow.", "source": "Sallatha Sutta — Buddhist teaching"},
  {"id": 238, "category": "Philosophy", "text": "Impermanence isn't a depressing doctrine — it's the reason anything matters. The Buddhist insight: clinging to what must change is the mechanism of suffering; loving what must change is the alternative.", "source": "Buddhist philosophy — anicca"},
  {"id": 239, "category": "Philosophy", "text": "Wu wei — effortless action. The Taoist ideal isn't laziness but the skill of the master: acting with the grain of the situation rather than against it, like a good sailor using the wind she cannot command.", "source": "Tao Te Ching — Lao Tzu"},
  {"id": 240, "category": "Philosophy", "text": "Water, the Taoist model: the softest thing in the world, yet it wears down the hardest. It wins by yielding, takes the shape of any container, and always finds the low path everyone else avoided.", "source": "Tao Te Ching — Lao Tzu"},
  {"id": 241, "category": "Philosophy", "text": "The usefulness of what isn't there: a wheel works because of the empty hub, a pot because of its hollow, a room because of its space. The Tao Te Ching's design lesson — value the emptiness you keep, not just what fills it.", "source": "Tao Te Ching, chapter 11 — Lao Tzu"},
  {"id": 242, "category": "Philosophy", "text": "Socrates' method was a confession: the beginning of wisdom is discovering how little you actually know. He was called the wisest man in Athens for one reason — he alone knew that he knew nothing.", "source": "Plato's Apology — Socrates"},
  {"id": 243, "category": "Philosophy", "text": "Aristotle: excellence is not an act but a habit — a settled disposition built by repetition. The popular one-liner 'we are what we repeatedly do' is actually Will Durant's summary of him, and it's a good one.", "source": "Nicomachean Ethics — Aristotle (summarised by Will Durant)"},
  {"id": 244, "category": "Philosophy", "text": "The golden mean: for Aristotle, virtue sits between two vices — courage between cowardice and recklessness, generosity between meanness and waste. The right amount is a skill, found by practice, not a formula.", "source": "Nicomachean Ethics — Aristotle"},
  {"id": 245, "category": "Philosophy", "text": "Eudaimonia — usually translated 'happiness' — actually means something closer to flourishing: a whole life of activity in accordance with excellence. Not a feeling you have, but a way you function.", "source": "Nicomachean Ethics — Aristotle"},
  {"id": 246, "category": "Philosophy", "text": "Kierkegaard's riddle: life can only be understood backwards, but it must be lived forwards. The meaning of what you're doing now may only become visible years later — proceed anyway.", "source": "Søren Kierkegaard — Journals"},
  {"id": 247, "category": "Philosophy", "text": "Camus and the absurd: the universe offers no inherent meaning, and humans demand it anyway. His answer wasn't despair but revolt — create meaning in full knowledge that you're the one creating it.", "source": "The Myth of Sisyphus — Albert Camus"},
  {"id": 248, "category": "Philosophy", "text": "One must imagine Sisyphus happy. Camus' scandalous conclusion: even a man condemned to roll a boulder forever can own his fate — the struggle itself toward the heights is enough to fill a heart.", "source": "The Myth of Sisyphus — Albert Camus"},
  {"id": 249, "category": "Philosophy", "text": "Sartre: existence precedes essence. You aren't born with a purpose to discover, like a knife made for cutting — you exist first and define yourself by what you do. Terrifying, and completely liberating.", "source": "Existentialism Is a Humanism — Jean-Paul Sartre"},
  {"id": 250, "category": "Philosophy", "text": "Schopenhauer's porcupine dilemma: porcupines in winter huddle for warmth, get pricked, move apart, get cold, and shuffle back — until they find the tolerable distance. Human intimacy works the same way, and the shuffling is normal.", "source": "Parerga and Paralipomena — Arthur Schopenhauer"},
  {"id": 251, "category": "Philosophy", "text": "Pascal's diagnosis: all of humanity's problems stem from our inability to sit quietly in a room alone. Written in the 1600s — several centuries before the infinite scroll proved him right.", "source": "Pensées — Blaise Pascal"},
  {"id": 252, "category": "Philosophy", "text": "Hume's bombshell: reason is, and ought only to be, the slave of the passions. Logic can calculate routes but never chooses destinations — every 'rational' plan is serving some feeling. Know which one yours serves.", "source": "A Treatise of Human Nature — David Hume"},
  {"id": 253, "category": "Philosophy", "text": "Alan Watts: life is not a journey with a destination — it's more like music. The point of a song isn't the final chord; you're supposed to dance while it plays. Whatever you're postponing living for, this is the song.", "source": "Alan Watts — lectures"},
  {"id": 254, "category": "Philosophy", "text": "Mill's wager: it is better to be a human being dissatisfied than a pig satisfied; better Socrates dissatisfied than a fool satisfied. Some discontent is the price of being awake — and worth paying.", "source": "Utilitarianism — John Stuart Mill"},
  {"id": 255, "category": "Wisdom", "text": "Naval's distinction: seek wealth, not money or status. Wealth is assets that earn while you sleep — businesses, investments, code, content. Money is how it transfers; status is a zero-sum game someone must lose.", "source": "The Almanack of Naval Ravikant"},
  {"id": 256, "category": "Wisdom", "text": "Play long-term games with long-term people. All the real returns in life — in wealth, knowledge, and relationships — come from compound interest, and compounding needs decades with people who won't defect.", "source": "The Almanack of Naval Ravikant"},
  {"id": 257, "category": "Wisdom", "text": "Specific knowledge is what you can't be trained for — the strange combination of skills, obsessions, and experiences that is yours alone. If society can train someone else to do it, eventually it'll be done cheaper. Build what only you can.", "source": "The Almanack of Naval Ravikant"},
  {"id": 258, "category": "Wisdom", "text": "Naval on desire: every desire is a contract you sign with yourself to be unhappy until you get what you want. Choose your desires very deliberately — you're choosing your future dissatisfactions.", "source": "The Almanack of Naval Ravikant"},
  {"id": 259, "category": "Wisdom", "text": "Read what you love until you love to read. The habit matters more than the syllabus — a person who devours 'unserious' books will out-learn a person who owns serious ones.", "source": "The Almanack of Naval Ravikant"},
  {"id": 260, "category": "Wisdom", "text": "Munger's career thesis: it is remarkable how much long-term advantage people like us have gotten by trying to be consistently not stupid, instead of trying to be very intelligent. Avoid the obvious errors; the rest sorts itself.", "source": "Poor Charlie's Almanack — Charlie Munger"},
  {"id": 261, "category": "Wisdom", "text": "'Show me the incentive and I will show you the outcome.' Munger's iron law: when behaviour confuses you, stop analysing the person and start analysing what they're rewarded for.", "source": "Poor Charlie's Almanack — Charlie Munger"},
  {"id": 262, "category": "Wisdom", "text": "Build a latticework of mental models. Munger: knowing isolated facts is useless — you need the big ideas from every discipline (compounding, feedback loops, incentives, evolution) hung on a framework, so experience has somewhere to stick.", "source": "Poor Charlie's Almanack — Charlie Munger"},
  {"id": 263, "category": "Wisdom", "text": "Munger on envy: it's the only deadly sin you can't possibly have any fun at. Gluttony and lust at least offer a good afternoon — envy is pure suffering with no upside, over someone else's life.", "source": "Charlie Munger — speeches"},
  {"id": 264, "category": "Wisdom", "text": "Take a simple idea and take it seriously. Most people know compounding, honesty, and showing up daily are powerful — and treat them as clichés. Munger's edge was treating the obvious as if it were true.", "source": "Charlie Munger — on simple ideas"},
  {"id": 265, "category": "Wisdom", "text": "Buffett on reputation: it takes twenty years to build and five minutes to ruin. If you think about that, you'll do things differently — every shortcut gets priced against two decades of trust.", "source": "Warren Buffett"},
  {"id": 266, "category": "Wisdom", "text": "Hanlon's razor: never attribute to malice what is adequately explained by carelessness, tiredness, or misunderstanding. It's statistically more accurate than suspicion — and it saves the enormous energy cost of being permanently wronged.", "source": "Hanlon's razor"},
  {"id": 267, "category": "Wisdom", "text": "Hard choices, easy life. Easy choices, hard life. Gregorek's formula: every difficult decision taken now — the training, the honest conversation, the saving — is a payment that makes the future simpler. Every dodge is a loan.", "source": "Jerzy Gregorek"},
  {"id": 268, "category": "Wisdom", "text": "The best time to plant a tree was twenty years ago. The second best time is now. The proverb's real target is the excuse hiding inside regret — being late is not a reason to be later.", "source": "Chinese proverb"},
  {"id": 269, "category": "Wisdom", "text": "Slow is smooth, smooth is fast. The special-forces maxim: rushing creates errors, errors create rework, and rework is slower than care. Speed is a downstream consequence of composure.", "source": "Military maxim"},
  {"id": 270, "category": "Wisdom", "text": "Measure twice, cut once. The carpenter's rule generalises everywhere: checking is cheap and irreversible actions are expensive. The ratio of planning to doing should scale with how permanent the cut is.", "source": "Carpenter's proverb"},
  {"id": 271, "category": "Wisdom", "text": "Don't let perfect be the enemy of good. The polished version that ships next year loses to the decent version that ships Friday and improves — in products, essays, workouts, and apologies.", "source": "Proverb, via Voltaire"},
  {"id": 272, "category": "Wisdom", "text": "When you find yourself in a hole, stop digging. The first rule of problems: before optimising your way out, check whether your current behaviour is the shovel.", "source": "Attributed to Will Rogers"},
  {"id": 273, "category": "Wisdom", "text": "If you want to go fast, go alone. If you want to go far, go together. The proverb encodes a real trade-off — solo speed versus collective endurance — and most big things are far, not fast.", "source": "Proverb, often cited as African"},
  {"id": 274, "category": "Wisdom", "text": "We have two ears and one mouth so that we can listen twice as much as we speak. The ancient ratio, attributed to Epictetus, remains the single most reliable way to become interesting: be interested.", "source": "Attributed to Epictetus"},
  {"id": 275, "category": "Wisdom", "text": "Confucius: real knowledge is to know the extent of one's ignorance. The educated fool and the wise person often hold similar amounts of information — the difference is an accurate map of the gaps.", "source": "Attributed to Confucius"},
  {"id": 276, "category": "Wisdom", "text": "Montaigne's confession: 'My life has been full of terrible misfortunes, most of which never happened.' A four-century-old reminder that the imagination bills you for disasters reality never delivers.", "source": "Attributed to Michel de Montaigne"},
  {"id": 277, "category": "Wisdom", "text": "Via negativa: improvement by removal. Taleb's principle — you often gain more by subtracting the bad (the toxic friend, the junk food, the losing habit) than by adding anything new. Addition is speculation; subtraction is proven.", "source": "Antifragile — Nassim Taleb"},
  {"id": 278, "category": "Wisdom", "text": "Antifragility: some things don't just survive shocks — they improve from them, like muscles from training and immune systems from exposure. Taleb's question for anything you build: does volatility hurt it, or feed it?", "source": "Antifragile — Nassim Taleb"},
  {"id": 279, "category": "Wisdom", "text": "The Lindy effect: for ideas, books, and technologies, life expectancy grows with age — what has lasted five hundred years will likely last five hundred more. When choosing what to learn, old and alive beats new and loud.", "source": "Antifragile — Nassim Taleb"},
  {"id": 280, "category": "Wisdom", "text": "Skin in the game: never take advice from someone who doesn't bear the cost of being wrong. The forecaster risks nothing; the practitioner risks everything. Weight opinions by exposure, not confidence.", "source": "Skin in the Game — Nassim Taleb"},
  {"id": 281, "category": "Wisdom", "text": "The second mouse gets the cheese. Being first is glamorous and often fatal; the fast follower learns from the pioneer's mistakes at a fraction of the cost. Sometimes the winning move is a well-timed second.", "source": "Proverb"},
  {"id": 282, "category": "Wisdom", "text": "Trust, but verify. The two halves need each other: trust without verification is naivety with a countdown; verification without trust makes cooperation impossible. Extend good faith — and check the work.", "source": "Russian proverb, popularised by Reagan"},
  {"id": 283, "category": "Wisdom", "text": "Give me six hours to chop down a tree and I will spend the first four sharpening the axe. The saying — attributed to Lincoln — survives because the ratio is roughly right: preparation is most of performance.", "source": "Attributed to Abraham Lincoln"},
  {"id": 284, "category": "Wisdom", "text": "The wound is the place where the light enters you. Rumi's line, eight centuries old, compresses the entire post-traumatic growth literature into eleven words.", "source": "Attributed to Rumi"},
  {"id": 285, "category": "Wisdom", "text": "How you do anything is how you do everything. The Zen-flavoured maxim is an audit tool: the corners cut when nobody's watching are the same corners cut when everything depends on it.", "source": "Zen saying"},
  {"id": 286, "category": "Wisdom", "text": "A person who chases two rabbits catches neither. The old proverb is a complete theory of focus in nine words — every additional priority halves the odds on all of them.", "source": "Proverb"},
  {"id": 287, "category": "Inspiring Quotes", "text": "\"Waste no more time arguing about what a good man should be. Be one.\"", "source": "Marcus Aurelius — Meditations"},
  {"id": 288, "category": "Inspiring Quotes", "text": "\"We suffer more often in imagination than in reality.\"", "source": "Seneca"},
  {"id": 289, "category": "Inspiring Quotes", "text": "\"No man is free who is not master of himself.\"", "source": "Epictetus"},
  {"id": 290, "category": "Inspiring Quotes", "text": "\"Nature does not hurry, yet everything is accomplished.\"", "source": "Attributed to Lao Tzu"},
  {"id": 291, "category": "Inspiring Quotes", "text": "\"Well done is better than well said.\"", "source": "Benjamin Franklin"},
  {"id": 292, "category": "Inspiring Quotes", "text": "\"Do what you can, with what you have, where you are.\"", "source": "Theodore Roosevelt"},
  {"id": 293, "category": "Inspiring Quotes", "text": "\"Comparison is the thief of joy.\"", "source": "Attributed to Theodore Roosevelt"},
  {"id": 294, "category": "Inspiring Quotes", "text": "\"It always seems impossible until it's done.\"", "source": "Attributed to Nelson Mandela"},
  {"id": 295, "category": "Inspiring Quotes", "text": "\"Don't count the days; make the days count.\"", "source": "Muhammad Ali"},
  {"id": 296, "category": "Inspiring Quotes", "text": "\"People will never forget how you made them feel.\"", "source": "Maya Angelou"},
  {"id": 297, "category": "Inspiring Quotes", "text": "\"Stay hungry. Stay foolish.\"", "source": "Whole Earth Catalog — made famous by Steve Jobs"},
  {"id": 298, "category": "Inspiring Quotes", "text": "\"I have not failed. I've just found 10,000 ways that won't work.\"", "source": "Attributed to Thomas Edison"},
  {"id": 299, "category": "Inspiring Quotes", "text": "\"The secret of getting ahead is getting started.\"", "source": "Attributed to Mark Twain"},
  {"id": 300, "category": "Inspiring Quotes", "text": "\"Knowing is not enough; we must apply.\"", "source": "Johann Wolfgang von Goethe"},
  {"id": 301, "category": "Inspiring Quotes", "text": "\"The world breaks every one and afterward many are strong at the broken places.\"", "source": "Ernest Hemingway — A Farewell to Arms"},
  {"id": 302, "category": "Inspiring Quotes", "text": "\"Be water, my friend.\"", "source": "Bruce Lee"},
  {"id": 303, "category": "Inspiring Quotes", "text": "\"Luck is what happens when preparation meets opportunity.\"", "source": "Attributed to Seneca"},
  {"id": 304, "category": "Inspiring Quotes", "text": "\"Not what we have but what we enjoy, constitutes our abundance.\"", "source": "Attributed to Epicurus"},
  {"id": 305, "category": "Inspiring Quotes", "text": "\"It takes very little to make a happy life.\"", "source": "Marcus Aurelius — Meditations (paraphrased)"},
  {"id": 306, "category": "Inspiring Quotes", "text": "\"Fall down seven times, stand up eight.\"", "source": "Japanese proverb"},
  {"id": 307, "category": "Inspiring Quotes", "text": "\"A smooth sea never made a skilled sailor.\"", "source": "Proverb"},
  {"id": 308, "category": "Inspiring Quotes", "text": "\"Life is either a daring adventure, or nothing.\"", "source": "Helen Keller"},
  {"id": 309, "category": "Inspiring Quotes", "text": "\"Action is the foundational key to all success.\"", "source": "Attributed to Pablo Picasso"},
  {"id": 310, "category": "Inspiring Quotes", "text": "\"I am not what happened to me, I am what I choose to become.\"", "source": "Attributed to Carl Jung"},
  {"id": 311, "category": "Inspiring Quotes", "text": "\"Live the questions now.\"", "source": "Rainer Maria Rilke — Letters to a Young Poet"},
  {"id": 312, "category": "Inspiring Quotes", "text": "\"Storms make trees take deeper roots.\"", "source": "Dolly Parton"},
  {"id": 313, "category": "Inspiring Quotes", "text": "\"You miss 100% of the shots you don't take.\"", "source": "Wayne Gretzky"},
  {"id": 314, "category": "Inspiring Quotes", "text": "\"The most effective way to do it, is to do it.\"", "source": "Amelia Earhart"},
  {"id": 315, "category": "Inspiring Quotes", "text": "\"The best way to predict the future is to create it.\"", "source": "Attributed to Peter Drucker"},
  {"id": 316, "category": "Inspiring Quotes", "text": "\"He who has a why to live can bear almost any how.\"", "source": "Friedrich Nietzsche"},
  {"id": 317, "category": "Inspiring Quotes", "text": "\"The unexamined life is not worth living.\"", "source": "Socrates, in Plato's Apology"},
  {"id": 318, "category": "Inspiring Quotes", "text": "\"Adopt the pace of nature: her secret is patience.\"", "source": "Attributed to Ralph Waldo Emerson"},
  {"id": 319, "category": "Business", "text": "Good is the enemy of great. Collins opens with it because it explains why greatness is rare: good schools, good companies, good lives are comfortable enough that almost nobody pushes past them.", "source": "Good to Great — Jim Collins"},
  {"id": 320, "category": "Business", "text": "First who, then what. Collins' research on great companies: get the right people on the bus and the wrong people off before deciding where to drive. With the right people, the destination problem largely solves itself.", "source": "Good to Great — Jim Collins"},
  {"id": 321, "category": "Business", "text": "The hedgehog concept: greatness lives at the intersection of three circles — what you can be the best in the world at, what drives your economic engine, and what you're deeply passionate about. Not two of three. All three.", "source": "Good to Great — Jim Collins"},
  {"id": 322, "category": "Business", "text": "The flywheel: great companies aren't built by one dramatic push but by consistent pushes in one direction until momentum takes over. From outside it looks like a breakthrough; from inside it was ten thousand turns.", "source": "Good to Great — Jim Collins"},
  {"id": 323, "category": "Business", "text": "Confront the brutal facts while retaining faith. Collins found great companies created cultures where hard truths surfaced fast and got acted on — bad news travelling quickly is a feature, not a morale problem.", "source": "Good to Great — Jim Collins"},
  {"id": 324, "category": "Business", "text": "Competition is for losers, in Thiel's provocation: perfect competition competes profits away to zero. The valuable business escapes comparison entirely — it does something so distinct it has pricing power. Aim for monopoly through uniqueness, not victory through sameness.", "source": "Zero to One — Peter Thiel"},
  {"id": 325, "category": "Business", "text": "Thiel's interview question: what important truth do very few people agree with you on? Every great business is built on a secret — something true about the world that the market hasn't priced in yet.", "source": "Zero to One — Peter Thiel"},
  {"id": 326, "category": "Business", "text": "To displace an incumbent, being slightly better isn't enough — switching costs eat small advantages. Thiel's rule of thumb: aim for a 10x improvement on some important dimension, or expect to be ignored.", "source": "Zero to One — Peter Thiel"},
  {"id": 327, "category": "Business", "text": "A startup is an experiment, not a small version of a big company. Ries' loop — build, measure, learn — exists to answer one question as cheaply as possible: should this product exist? Find out before scaling, not after.", "source": "The Lean Startup — Eric Ries"},
  {"id": 328, "category": "Business", "text": "The minimum viable product isn't a bad product — it's the smallest thing that generates real learning from real customers. Every feature built before that first contact is a guess wearing a suit.", "source": "The Lean Startup — Eric Ries"},
  {"id": 329, "category": "Business", "text": "Vanity metrics — downloads, page views, registered users — go up and to the right while the business dies. Ries: track the numbers that change decisions — activation, retention, revenue per customer.", "source": "The Lean Startup — Eric Ries"},
  {"id": 330, "category": "Business", "text": "A pivot is a change of strategy without a change of vision. The skill isn't stubbornness or flexibility — it's knowing which layer you're revising: the mission stays, the method is disposable.", "source": "The Lean Startup — Eric Ries"},
  {"id": 331, "category": "Business", "text": "The hard thing about hard things is that there's no formula. Horowitz's comfort for founders: the struggle — sleepless, doubting, improvising — isn't a sign you're doing it wrong. It's what building something is like.", "source": "The Hard Thing About Hard Things — Ben Horowitz"},
  {"id": 332, "category": "Business", "text": "Take care of the people, the products, and the profits — in that order. Horowitz's ordering is deliberate: get the first one wrong and the other two stop mattering fairly quickly.", "source": "The Hard Thing About Hard Things — Ben Horowitz"},
  {"id": 333, "category": "Business", "text": "Work on your business, not just in it. Gerber's diagnosis of small-business failure: technicians who can do the work but never build the systems that let the business run without them — so they've bought a job, not built an asset.", "source": "The E-Myth Revisited — Michael Gerber"},
  {"id": 334, "category": "Business", "text": "Build the business as if you'll franchise it: document every process so an ordinary person can produce an extraordinary result. Systems run the business; people run the systems.", "source": "The E-Myth Revisited — Michael Gerber"},
  {"id": 335, "category": "Business", "text": "Drucker's foundation: the purpose of a business is to create a customer. Not to maximise profit — profit is the test of validity. Everything starts from someone outside the building saying yes.", "source": "The Practice of Management — Peter Drucker"},
  {"id": 336, "category": "Business", "text": "The essence of strategy is choosing what not to do. Porter: activities that fit and reinforce each other create advantage — and every yes to an off-strategy opportunity weakens the fit that was the whole point.", "source": "Michael Porter — 'What Is Strategy?'"},
  {"id": 337, "category": "Business", "text": "It's still Day 1. Bezos' warning: Day 2 is stasis, followed by irrelevance, followed by decline. The symptoms — managing by proxy, resisting trends, slow decisions — all treatable if caught early.", "source": "Jeff Bezos — shareholder letters"},
  {"id": 338, "category": "Business", "text": "'Your margin is my opportunity.' Bezos' line is a scanner for both attack and defence: every fat, comfortable margin in any industry is an invitation someone is eventually going to accept.", "source": "Jeff Bezos"},
  {"id": 339, "category": "Business", "text": "Focus on what won't change. Bezos built around the safe bets — customers will always want lower prices, faster delivery, bigger selection — because you can invest in a certainty for decades.", "source": "Jeff Bezos — on strategy"},
  {"id": 340, "category": "Business", "text": "Revenue is vanity, profit is sanity, cash is reality. Businesses rarely die from lack of profit on paper — they die when the bank account hits zero. Watch the cash conversion cycle, not just the P&L.", "source": "Business maxim"},
  {"id": 341, "category": "Business", "text": "Get the unit economics right before scaling. If you lose money on each customer, volume is a losing bet multiplied. Growth amplifies whatever the machine already does — including losses.", "source": "Startup economics"},
  {"id": 342, "category": "Business", "text": "A moat is whatever makes your advantage durable: switching costs, network effects, brand, cost advantages, or regulation. Without one, today's profits are simply an advertisement inviting competitors.", "source": "Warren Buffett — the moat concept"},
  {"id": 343, "category": "Business", "text": "Do things that don't scale. Paul Graham's advice to founders: recruit users one by one, deliver service that's absurdly manual, delight people personally. The unscalable phase is how you learn what to eventually scale.", "source": "Paul Graham — essays"},
  {"id": 344, "category": "Business", "text": "Make something people want. Y Combinator's entire philosophy in four words — most failed startups die not from competition or funding but from building, very efficiently, something nobody needed.", "source": "Y Combinator motto — Paul Graham"},
  {"id": 345, "category": "Business", "text": "1,000 true fans: a creator or niche business needs only about a thousand people who'll buy anything you make — at £100 a year each, that's a living. The internet made small, deep audiences a viable business model.", "source": "1,000 True Fans — Kevin Kelly"},
  {"id": 346, "category": "Business", "text": "Price on value, not cost. Cost-plus pricing leaves money on the table and ignores the only question that matters: what is this worth to the buyer? The same hour of work is worth wildly different amounts to different customers.", "source": "Pricing strategy principle"},
  {"id": 347, "category": "Business", "text": "Word of mouth is the only marketing channel with negative cost: it compounds, it's trusted, and it improves with product quality. The best marketing budget is often spent on making the thing worth talking about.", "source": "Marketing principle"},
  {"id": 348, "category": "Business", "text": "Kaizen: continuous improvement in small steps, by everyone, every day. Toyota's insight was that a thousand 1% improvements from the people doing the work beat one grand redesign from the people who aren't.", "source": "The Toyota Way — Jeffrey Liker"},
  {"id": 349, "category": "Business", "text": "Chouinard built Patagonia on a heresy: make it so well it never needs replacing, tell people to buy less, and repair what they own. Quality as the business model turned out to be a moat nobody could copy cheaply.", "source": "Let My People Go Surfing — Yvon Chouinard"},
  {"id": 350, "category": "Business", "text": "Recurring revenue is worth a multiple of one-off revenue for a reason: it converts every sale from an event into a relationship, and makes the future partly predictable. Build things people subscribe to, return to, or renew.", "source": "Business model design"},
  {"id": 351, "category": "Management", "text": "Grove's equation: a manager's output equals the output of their team plus the output of every team they influence. Your personal productivity is now a rounding error — leverage is the job.", "source": "High Output Management — Andy Grove"},
  {"id": 352, "category": "Management", "text": "Rank every activity by leverage: a one-hour training session that lifts ten people's performance for a year beats a week of doing the work yourself. Grove: high-leverage activities are the only ones worth a manager's calendar.", "source": "High Output Management — Andy Grove"},
  {"id": 353, "category": "Management", "text": "Task-relevant maturity: how closely you manage someone should depend on their experience with this specific task, not their seniority. A veteran doing something new needs structure; a junior doing their specialty needs room.", "source": "High Output Management — Andy Grove"},
  {"id": 354, "category": "Management", "text": "The one-to-one belongs to the report, not the manager. Grove: it's their agenda, their problems, their career — your job is to listen and unblock. Cancel it regularly and you're cancelling your information supply.", "source": "High Output Management — Andy Grove"},
  {"id": 355, "category": "Management", "text": "Radical candour is caring personally while challenging directly. Scott's map of the failures: challenge without care is obnoxious aggression; care without challenge — the most common failure — is ruinous empathy that lets people fail slowly.", "source": "Radical Candor — Kim Scott"},
  {"id": 356, "category": "Management", "text": "'Clear is kind. Unclear is unkind.' Brené Brown's rule for hard conversations: fudging the message to spare feelings just outsources the pain to later — with interest.", "source": "Dare to Lead — Brené Brown"},
  {"id": 357, "category": "Management", "text": "Push authority to the information, not information to the authority. Marquet turned the worst submarine in the fleet into the best by having officers state 'I intend to...' instead of asking permission — competence and clarity followed ownership.", "source": "Turn the Ship Around! — David Marquet"},
  {"id": 358, "category": "Management", "text": "For any work requiring thought, carrots and sticks backfire. Pink's synthesis of the research: cognitive performance runs on autonomy, mastery, and purpose. Pay enough to take money off the table — then get out of the way.", "source": "Drive — Daniel Pink"},
  {"id": 359, "category": "Management", "text": "Multipliers versus diminishers: some leaders get 2x from their people by asking hard questions and giving ownership; others get half by having all the answers. Wiseman's finding — the diminishers usually think they're multipliers.", "source": "Multipliers — Liz Wiseman"},
  {"id": 360, "category": "Management", "text": "People join companies and leave managers. Gallup's data across millions of employees: the single biggest driver of engagement and retention is the immediate boss — not pay, perks, or brand.", "source": "First, Break All the Rules — Buckingham & Coffman"},
  {"id": 361, "category": "Management", "text": "Manage to strengths, not around weaknesses. The Gallup finding: great managers cast people into roles where their natural patterns are useful, rather than sanding everyone into adequate all-rounders.", "source": "First, Break All the Rules — Buckingham & Coffman"},
  {"id": 362, "category": "Management", "text": "Psychological safety — the shared belief that you can speak up, admit error, and ask questions without punishment — was the top predictor of team performance in Google's Project Aristotle. Smart people go quiet in unsafe rooms.", "source": "Amy Edmondson's research; Google's Project Aristotle"},
  {"id": 363, "category": "Management", "text": "Trust is the base of the pyramid. Lencioni: without it, people hide weaknesses, conflict goes underground, commitments are fake, and accountability is impossible. Every dysfunction upstairs traces to a trust problem downstairs.", "source": "The Five Dysfunctions of a Team — Patrick Lencioni"},
  {"id": 364, "category": "Management", "text": "Healthy teams argue. Lencioni's inversion: artificial harmony is a dysfunction — when nobody debates, the real conversations happen in corridors after the meeting. Conflict about ideas, in the room, is what commitment is made of.", "source": "The Five Dysfunctions of a Team — Patrick Lencioni"},
  {"id": 365, "category": "Management", "text": "Feedback that works is specific and immediate: situation, behaviour, impact. 'In Tuesday's call, when you interrupted the client twice, we lost the thread of their objection.' No character verdicts, no 'always', no waiting for the annual review.", "source": "SBI model — Center for Creative Leadership"},
  {"id": 366, "category": "Management", "text": "Praise in public, correct in private. The asymmetry is deliberate: public praise multiplies through the team; public correction teaches everyone watching to hide their mistakes from you.", "source": "Management maxim"},
  {"id": 367, "category": "Management", "text": "Delegate outcomes, not methods. Define what done looks like, the constraints, and the deadline — then let them choose the route. Prescribing every step gets you compliance, a bottleneck, and nobody who can think when you're away.", "source": "Delegation practice"},
  {"id": 368, "category": "Management", "text": "Who's got the monkey? Oncken's classic: every time you say 'leave it with me,' a problem jumps from your report's back to yours. By Friday you're doing five people's thinking. Keep the monkey with its owner; offer help feeding it.", "source": "'Who's Got the Monkey?' — William Oncken, HBR"},
  {"id": 369, "category": "Management", "text": "Context, not control. The Netflix principle: give people the strategy, the numbers, and the stakes — then let them decide. If you have to control decisions, you either hired wrong or informed badly.", "source": "No Rules Rules — Hastings & Meyer"},
  {"id": 370, "category": "Management", "text": "Disagree and commit. Bezos' mechanism for speed: argue hard, then — once a decision is made — everyone executes as if it were their own idea. The alternative is slow consensus followed by quiet sabotage.", "source": "Jeff Bezos — shareholder letters"},
  {"id": 371, "category": "Management", "text": "Two-pizza teams: if a team can't be fed with two pizzas, it's too big. Communication paths grow with the square of headcount — a team of 6 has 15 relationships to maintain; a team of 12 has 66.", "source": "Amazon's two-pizza rule"},
  {"id": 372, "category": "Management", "text": "Goodhart's law: when a measure becomes a target, it ceases to be a good measure. Reward lines of code and you get long programs; reward call times and customers get hung up on. Metrics need a paired counter-metric.", "source": "Goodhart's law"},
  {"id": 373, "category": "Management", "text": "Brooks' law: adding people to a late software project makes it later. Onboarding costs, communication overhead, and divided work mean the ninth month cannot be bought with nine more mothers.", "source": "The Mythical Man-Month — Fred Brooks"},
  {"id": 374, "category": "Management", "text": "Parkinson's law: work expands to fill the time available. The countermove is deliberate under-allocation — the report that gets a day takes a day; the same report given a week takes a week and isn't better.", "source": "Parkinson's Law — C. Northcote Parkinson"},
  {"id": 375, "category": "Management", "text": "Every meeting needs an owner, a decision or purpose, and a written outcome — or it shouldn't exist. Meetings are the most expensive thing a company does per hour; treat the calendar like the budget it is.", "source": "Meeting hygiene — High Output Management tradition"},
  {"id": 376, "category": "Management", "text": "Hire for slope, not intercept. Current skills are where someone starts; rate of learning is where they'll be in two years. Given the choice, the steep learner overtakes the polished veteran surprisingly fast.", "source": "Tech hiring maxim — popularised by John Ousterhout"},
  {"id": 377, "category": "Management", "text": "A players hire A players; B players hire C players. The attributed Silicon Valley law: insecure managers hire people who won't threaten them, and the quality bar ratchets down one level per hiring generation.", "source": "Attributed to Steve Jobs / Silicon Valley maxim"},
  {"id": 378, "category": "Management", "text": "The standard you walk past is the standard you accept. The line from Lieutenant General Morrison: every ignored corner-cut, late arrival, or small disrespect becomes policy the moment a leader sees it and says nothing.", "source": "David Morrison — Australian Army address"},
  {"id": 379, "category": "Management", "text": "Train people well enough that they could leave; treat them well enough that they don't want to. Branson's formulation resolves the fake dilemma managers use to justify under-investing in their best people.", "source": "Attributed to Richard Branson"},
  {"id": 380, "category": "Management", "text": "Assume positive intent, then address the behaviour. Most workplace friction is two reasonable people with different information. Starting from 'they're probably not an idiot or a villain' keeps the conversation about the problem.", "source": "Management practice — attribution at work"},
  {"id": 381, "category": "Longevity", "text": "Healthspan versus lifespan: the goal isn't just more years, but more years you'd actually want. Attia's reframe — most people spend their last decade in decline; the project is compressing that decline into as short a window as possible.", "source": "Outlive — Peter Attia"},
  {"id": 382, "category": "Longevity", "text": "Medicine 2.0 treats disease after it appears; Medicine 3.0 works decades earlier, on the risk curve. The diseases that kill most people — heart disease, cancer, neurodegeneration, metabolic disease — take 20+ years to develop. That's your head start.", "source": "Outlive — Peter Attia"},
  {"id": 383, "category": "Longevity", "text": "Attia's 'four horsemen': heart disease, cancer, neurodegenerative disease, and metabolic dysfunction cause the overwhelming majority of deaths in developed countries — and metabolic health quietly feeds the other three.", "source": "Outlive — Peter Attia"},
  {"id": 384, "category": "Longevity", "text": "Train for the centenarian decathlon: list the specific things you want to do at 85 — lift a grandchild, climb stairs with shopping, get up off the floor — and work backwards. Capacity declines, so you must build a surplus now.", "source": "Outlive — Peter Attia"},
  {"id": 385, "category": "Longevity", "text": "VO2 max — your aerobic engine size — may be the single strongest modifiable predictor of lifespan. In one large study, moving from low to even below-average fitness cut mortality risk more than quitting smoking.", "source": "Outlive — Peter Attia; Mandsager et al., JAMA"},
  {"id": 386, "category": "Longevity", "text": "Muscle is a longevity organ: it's your largest site for glucose disposal, your metabolic reserve for surviving illness, and its strength predicts survival. Sarcopenia — age-related muscle loss — is a disease you can train against.", "source": "Outlive — Peter Attia"},
  {"id": 387, "category": "Longevity", "text": "Grip strength is a startlingly good mortality predictor in large studies — not because gripping matters, but because it's a proxy for total-body strength and neurological health. The fix isn't hand exercises; it's getting strong everywhere.", "source": "PURE study — Leong et al., The Lancet"},
  {"id": 388, "category": "Longevity", "text": "Falls are among the leading causes of injury death in older adults, and the fear of falling shrinks lives long before a fall does. Balance and stability training now is the cheapest insurance policy in medicine.", "source": "Outlive — Peter Attia; falls epidemiology"},
  {"id": 389, "category": "Longevity", "text": "A simple screening test: in middle age, being unable to balance on one leg for 10 seconds was associated with substantially higher mortality over the following years in a large cohort study. Practise until it's easy.", "source": "Araujo et al., British Journal of Sports Medicine"},
  {"id": 390, "category": "Longevity", "text": "Know your ApoB. Attia argues it's the number that best captures the particles that actually cause atherosclerosis — better than standard cholesterol panels. Heart disease is slow, cumulative, and largely preventable if you start early.", "source": "Outlive — Peter Attia"},
  {"id": 391, "category": "Longevity", "text": "Blood pressure is the silent multiplier: it damages arteries, heart, kidneys, and brain for decades with zero symptoms. It's also cheap to measure at home and very treatable. Not knowing yours is a choice.", "source": "Cardiovascular prevention research"},
  {"id": 392, "category": "Longevity", "text": "Hormesis: controlled doses of stress — exercise, heat, cold, fasting — trigger repair responses that leave the body stronger than before. The dose makes the medicine; the same stress uncontrolled and chronic is just damage.", "source": "Lifespan — David Sinclair"},
  {"id": 393, "category": "Longevity", "text": "The Finnish sauna data: men using a sauna 4–7 times per week had roughly half the fatal heart disease risk of once-a-week users over two decades of follow-up. Heat exposure looks like exercise's quiet cousin.", "source": "Laukkanen et al., JAMA Internal Medicine"},
  {"id": 394, "category": "Longevity", "text": "In every Blue Zone, movement isn't exercise — it's engineered into life: gardens, stairs, walking to neighbours, kneading dough. Buettner's point: environments that nudge motion beat gym memberships that require decisions.", "source": "The Blue Zones — Dan Buettner"},
  {"id": 395, "category": "Longevity", "text": "Purpose is worth years. Okinawans call it ikigai, Costa Ricans plan de vida — the reason to get up in the morning. Studies link a strong sense of purpose with meaningfully lower mortality. Retirement from work shouldn't mean retirement from purpose.", "source": "The Blue Zones — Dan Buettner"},
  {"id": 396, "category": "Longevity", "text": "Belonging shows up in every Blue Zone: lifelong friends, family kept close, community woven into the week. Buettner's observation — the world's longest-lived people didn't pursue longevity; their social lives produced it as a side effect.", "source": "The Blue Zones — Dan Buettner"},
  {"id": 397, "category": "Longevity", "text": "Loneliness is a health exposure, not just a feeling: Holt-Lunstad's meta-analysis put weak social connection in the same mortality risk league as smoking up to 15 cigarettes a day. Friendship maintenance is preventative medicine.", "source": "Holt-Lunstad et al. — social connection meta-analysis"},
  {"id": 398, "category": "Longevity", "text": "Sleep is when the maintenance crew works: memory consolidation, tissue repair, and the brain's waste-clearance system all run mostly during sleep. Chronic short sleep is linked to worse outcomes across nearly every major disease.", "source": "Why We Sleep — Matthew Walker"},
  {"id": 399, "category": "Longevity", "text": "Sleep regularity may matter as much as duration: large cohort data show people with consistent sleep-wake times have notably lower mortality risk than irregular sleepers — even at similar total hours. Same time every day, including weekends.", "source": "Sleep regularity research — Windred et al."},
  {"id": 400, "category": "Longevity", "text": "Hearing loss is one of the largest modifiable risk factors for dementia identified by the Lancet Commission — and a major trial found hearing aids slowed cognitive decline in high-risk older adults. Get tested; wear the aids.", "source": "Lancet Commission on dementia; ACHIEVE trial"},
  {"id": 401, "category": "Longevity", "text": "Protein needs rise with age. Older muscles respond less to each meal — anabolic resistance — so many researchers recommend well above the standard minimum, spread across the day, to hold onto muscle through later decades.", "source": "Protein and ageing research"},
  {"id": 402, "category": "Longevity", "text": "The compression of morbidity: the aim, coined by Stanford's James Fries, is to shorten the sick period at the end of life, not just extend the total. Live long, stay capable, decline briefly. Everything on this list serves that shape.", "source": "James Fries — compression of morbidity"},
  {"id": 403, "category": "Longevity", "text": "Modern evidence has turned against the nightly-glass-of-wine story: large genetic studies find no protective level of alcohol for most outcomes, and risk rises with dose. If you drink, drink for pleasure, knowingly — not for your heart.", "source": "Alcohol and health — Mendelian randomisation studies"},
  {"id": 404, "category": "Longevity", "text": "Flossing and long life sound unrelated, but gum disease tracks with cardiovascular risk in study after study — chronic low-grade inflammation is the suspected bridge. The mouth is part of the body; treat it like it counts.", "source": "Periodontal-cardiovascular research"},
  {"id": 405, "category": "Longevity", "text": "Stairs are a free longevity lab: regular stair climbing shows up in cohort studies associated with lower cardiovascular risk, and refusing the lift builds leg power — the capacity that keeps older adults independent.", "source": "Stair climbing cohort research"},
  {"id": 406, "category": "Longevity", "text": "Don't smoke remains the single most powerful longevity intervention known — smoking takes roughly a decade off life expectancy, and quitting at any age claws a surprising amount back. Everything else on this list is fine-tuning by comparison.", "source": "Doll & Peto — British Doctors Study"},
  {"id": 407, "category": "Longevity", "text": "Attia's often-quoted framing: exercise is the closest thing we have to a longevity drug. If its effects — on heart disease, cancer, dementia, and all-cause mortality — came in a pill, everyone would take it at any price.", "source": "Outlive — Peter Attia"},
  {"id": 408, "category": "Longevity", "text": "Emotional health is a pillar, not a footnote. Attia calls it the part of longevity he nearly failed: a long life estranged, bitter, or numb isn't the goal. Therapy, relationships, and meaning belong in the training plan.", "source": "Outlive — Peter Attia"},
  {"id": 409, "category": "Longevity", "text": "Metabolic health is upstream of almost everything: insulin resistance quietly raises risk for heart disease, cancer, and dementia years before diabetes appears. Waist size, fasting glucose, and triglycerides tell you early.", "source": "Outlive — Peter Attia; metabolic syndrome research"},
  {"id": 410, "category": "Longevity", "text": "Your 60s and 70s are built in your 40s and 50s. Bone density, muscle mass, and aerobic capacity all peak and then decline — the higher the peak and the slower the slide, the later you cross the disability threshold. Start the deposit now.", "source": "Physiological reserve research"},
  {"id": 411, "category": "Exercise", "text": "Exercise is fertiliser for the brain: it triggers BDNF, a protein Ratey calls 'Miracle-Gro for the brain,' which supports learning and the growth of new connections. A workout before studying isn't a distraction — it's preparation.", "source": "Spark — John Ratey"},
  {"id": 412, "category": "Exercise", "text": "In the SMILE trial, structured aerobic exercise performed comparably to a leading antidepressant for major depression over 16 weeks — with lower relapse in the exercise group at follow-up. Movement is legitimate mental-health treatment.", "source": "Spark — John Ratey; Blumenthal's SMILE study"},
  {"id": 413, "category": "Exercise", "text": "Humans evolved to move only when necessary — which means being 'bad at exercising' is normal, not a character flaw. Lieberman's advice: stop moralising, make movement social and necessary, and let biology follow.", "source": "Exercised — Daniel Lieberman"},
  {"id": 414, "category": "Exercise", "text": "Use it or lose it is real biology: the body ruthlessly decommissions capacity it isn't asked for — muscle, bone, aerobic enzymes. Lieberman: physical activity doesn't just spend energy, it signals every repair system to keep running.", "source": "Exercised — Daniel Lieberman"},
  {"id": 415, "category": "Exercise", "text": "Adults lose roughly 3–8% of muscle mass per decade after 30, accelerating after 60 — unless they train. Resistance work doesn't just slow the slide; studies show people in their 80s and 90s still build meaningful strength.", "source": "Sarcopenia research — Fiatarone's nursing home trials"},
  {"id": 416, "category": "Exercise", "text": "Progressive overload is the whole secret of strength: gradually ask slightly more of the muscle — a little more weight, one more rep — and it adapts. No progression, no adaptation, no matter how sweaty the session.", "source": "Strength training principle"},
  {"id": 417, "category": "Exercise", "text": "Compound movements — squat, hinge, push, pull, carry — train dozens of muscles, the nervous system, and real-world capacity in a handful of exercises. If time is short, they're 80% of the value.", "source": "Strength training practice"},
  {"id": 418, "category": "Exercise", "text": "Zone 2 — the pace where you can still hold a conversation, just — builds the mitochondrial base that everything else sits on. Attia and coaches like San Millán prescribe it as the biggest slice of aerobic training, even for elites.", "source": "Zone 2 training — Iñigo San Millán / Peter Attia"},
  {"id": 419, "category": "Exercise", "text": "The Norwegian 4x4 for the top end: four rounds of four minutes hard (breathing heavily, just able to continue), three minutes easy between. A well-studied protocol for raising VO2 max — one session a week moves the needle.", "source": "4x4 interval research — Helgerud et al."},
  {"id": 420, "category": "Exercise", "text": "The step-count sweet spot: large pooled studies find mortality risk falls steeply up to roughly 7,000–8,000 steps a day, then flattens. You don't need 10,000 — that number came from a 1960s Japanese pedometer marketing campaign.", "source": "Step count meta-analyses — Paluch et al."},
  {"id": 421, "category": "Exercise", "text": "Exercise snacks count: studies of brief vigorous bursts in daily life — a minute or two of fast stair climbing or hard walking, a few times a day — found associations with substantially lower mortality in non-exercisers.", "source": "VILPA research — Stamatakis et al., Nature Medicine"},
  {"id": 422, "category": "Exercise", "text": "Sitting isn't the new smoking, but unbroken sitting is a real problem — and the antidote is cheap: regular movement breaks. Frequent short interruptions of sitting improve glucose and circulation markers even without formal workouts.", "source": "Sedentary behaviour research"},
  {"id": 423, "category": "Exercise", "text": "Combining cardio and strength beats either alone: pooled studies show the lowest mortality in people who do both aerobic work and resistance training. They're not competing programmes — they're two halves of one.", "source": "Combined training meta-analyses"},
  {"id": 424, "category": "Exercise", "text": "Adaptation happens during recovery, not during training. The workout is the stimulus; sleep and rest days are when the body rebuilds stronger. Training hard on chronic under-recovery is spending from an account with nothing in it.", "source": "Training adaptation — supercompensation principle"},
  {"id": 425, "category": "Exercise", "text": "Adherence is the best predictor of results — better than programme choice. The mediocre plan you follow for two years beats the perfect plan you quit in March. Choose the training you'll actually keep doing.", "source": "Exercise adherence research"},
  {"id": 426, "category": "Exercise", "text": "Motivation follows action, not the other way round. Behavioural activation research: start the warm-up on the days you least feel like it, and the wanting usually arrives a few minutes in. The rule is 'show up, then decide.'", "source": "Behavioural activation — mood and movement research"},
  {"id": 427, "category": "Exercise", "text": "Grease the groove: practise a movement frequently, fresh, and far from failure — a few pull-ups every time you pass the bar. Pavel's principle treats strength as a skill: the nervous system learns what it rehearses.", "source": "Pavel Tsatsouline — grease the groove"},
  {"id": 428, "category": "Exercise", "text": "Learn the difference between soreness and pain. Dull, symmetrical, next-day muscle ache is adaptation; sharp, localised, or joint pain during a movement is information. Train through the first; investigate the second.", "source": "Sports medicine practice"},
  {"id": 429, "category": "Exercise", "text": "Rucking — walking with weight on your back — is Lieberman-approved evolutionary exercise: humans are built for loaded carrying. It turns an ordinary walk into cardio plus strength plus posture work with zero skill required.", "source": "Exercised — Daniel Lieberman; rucking practice"},
  {"id": 430, "category": "Exercise", "text": "Post-exercise mood improvement is one of the most replicated findings in the field: a single session of moderate exercise reliably reduces anxiety and lifts mood for hours. On your worst days, the minimum session is the priority, not the exception.", "source": "Acute exercise and affect research"},
  {"id": 431, "category": "Exercise", "text": "Morning training wins on adherence: fewer schedule collisions, decision made before the day's willpower drains, and the streak protects itself. The best time to train is the time that survives your calendar.", "source": "Exercise timing and adherence research"},
  {"id": 432, "category": "Exercise", "text": "Warm up by rehearsing, not stretching: light cardio then progressively heavier versions of the movements you're about to do. Long static stretching before strength work can temporarily reduce power — save it for after.", "source": "Warm-up research — dynamic vs static stretching"},
  {"id": 433, "category": "Exercise", "text": "NEAT — non-exercise activity thermogenesis — is all the calories burned by fidgeting, standing, walking, and daily motion. It varies by hundreds of calories a day between people and often falls when you start dieting. Guard it: keep moving between workouts.", "source": "NEAT research — James Levine"},
  {"id": 434, "category": "Exercise", "text": "Train power, not just strength, as you age: the ability to produce force quickly declines faster than strength itself, and it's what catches a trip before it becomes a fall. Controlled fast movements — even sit-to-stands done briskly — keep it.", "source": "Power decline and ageing research"},
  {"id": 435, "category": "Exercise", "text": "A deload isn't slacking. Every few weeks of hard training, an easy week lets accumulated fatigue clear and adaptations show up. The plateau you're smashing yourself against is often just unshed fatigue.", "source": "Periodisation practice"},
  {"id": 436, "category": "Exercise", "text": "Walking meetings solve two problems at once: Stanford research found walking substantially boosts creative idea generation, and the steps come free. Take the phone call on your feet.", "source": "Oppezzo & Schwartz — Stanford walking creativity study"},
  {"id": 437, "category": "Exercise", "text": "Masters athletes show what ageing without detraining looks like: muscle cross-sections of lifelong exercisers in their 70s can resemble those of people decades younger. Much of what we call ageing is measurable disuse.", "source": "Masters athlete muscle studies — Wroblewski et al."},
  {"id": 438, "category": "Exercise", "text": "Track something. A training log — weights lifted, distances, times — turns vague effort into visible progress, and visible progress is the most reliable motivation there is. What gets recorded gets repeated.", "source": "Self-monitoring research in exercise"},
  {"id": 439, "category": "Exercise", "text": "The talk test beats gadgets for intensity: full sentences comfortably = easy aerobic; short phrases = moderate; single words = hard. It self-calibrates to your fitness on any given day, which no fixed heart-rate number does.", "source": "Talk test validation research"},
  {"id": 440, "category": "Exercise", "text": "Exercise improves focus for ADHD-type attention in both kids and adults — Ratey documents schools where morning exercise transformed classroom performance. If your concentration is broken, a hard 20 minutes is often faster than more coffee.", "source": "Spark — John Ratey"},
  {"id": 441, "category": "Diet", "text": "Eat food. Not too much. Mostly plants. Seven words that outperform most diet books. 'Food' means things your great-grandmother would recognise — not edible food-like substances engineered in labs.", "source": "Michael Pollan — In Defense of Food"},
  {"id": 442, "category": "Diet", "text": "The great-grandmother rule: if she wouldn't recognise it as food, think twice. Go-Gurt tubes, neon cereals, and squeezable yoghurt would baffle her. Apples, eggs, and lentils would not.", "source": "Michael Pollan — Food Rules"},
  {"id": 443, "category": "Diet", "text": "Eat things made from plants, not things made in plants. The distinction between a potato and a potato-based snack product is the distinction that matters most in a modern supermarket.", "source": "Michael Pollan — Food Rules"},
  {"id": 444, "category": "Diet", "text": "Over half the calories the average UK adult eats are ultra-processed — industrial formulations of extracted substances that barely resemble food. No other country in Europe comes close.", "source": "Chris van Tulleken — Ultra-Processed People"},
  {"id": 445, "category": "Diet", "text": "In a controlled NIH trial, people offered ultra-processed food ate about 500 more calories a day than the same people offered unprocessed meals matched for nutrients — and they gained weight without trying to.", "source": "Kevin Hall — NIH randomised trial, 2019"},
  {"id": 446, "category": "Diet", "text": "Food order matters: eating vegetables first, then protein and fat, then starches and sugars, flattens the glucose spike from the same meal. The fibre forms a mesh that slows sugar absorption.", "source": "Jessie Inchauspé — Glucose Revolution"},
  {"id": 447, "category": "Diet", "text": "A tablespoon of vinegar in water before a carb-heavy meal blunts the glucose spike. The acetic acid temporarily slows the enzyme that breaks starch into sugar.", "source": "Jessie Inchauspé — Glucose Revolution"},
  {"id": 448, "category": "Diet", "text": "A savoury breakfast built on protein steadies your whole day. Starting with sweet cereal or juice sets off a spike-crash-crave cycle that makes you hungrier by mid-morning.", "source": "Jessie Inchauspé — Glucose Revolution"},
  {"id": 449, "category": "Diet", "text": "A ten-minute walk after eating uses your muscles to soak up glucose as it enters the bloodstream, softening the spike. The cheapest metabolic intervention available happens to be free.", "source": "Jessie Inchauspé — Glucose Revolution"},
  {"id": 450, "category": "Diet", "text": "Put clothing on your carbs: pairing bread, rice, or pasta with fibre, protein, or fat slows digestion and flattens the glucose response compared with eating them naked.", "source": "Jessie Inchauspé — Glucose Revolution"},
  {"id": 451, "category": "Diet", "text": "The protein leverage hypothesis: humans keep eating until protein needs are met. Dilute your diet with low-protein processed food and your appetite drives you to overeat everything else in pursuit of it.", "source": "Raubenheimer & Simpson — Eat Like the Animals"},
  {"id": 452, "category": "Diet", "text": "Spreading protein across the day beats cramming it into dinner. Muscle protein synthesis responds meal by meal, so roughly even doses at each sitting keep the building signal switched on.", "source": "Protein distribution research — sports nutrition"},
  {"id": 453, "category": "Diet", "text": "Barely one adult in ten hits the 30-gram daily fibre target. Fibre feeds your gut bacteria, steadies blood sugar, and lowers heart disease risk — it may be the single most under-consumed nutrient.", "source": "UK dietary surveys — fibre intake"},
  {"id": 454, "category": "Diet", "text": "People who eat 30 or more different plant foods a week have measurably more diverse gut microbiomes than those eating fewer than ten. Diversity of plants — including herbs, seeds, and spices — beats quantity of any single one.", "source": "American Gut Project"},
  {"id": 455, "category": "Diet", "text": "In a Stanford trial, a diet high in fermented foods — yoghurt, kefir, kimchi, sauerkraut — increased gut microbiome diversity and lowered inflammatory markers in just ten weeks.", "source": "Stanford fermented foods study, 2021"},
  {"id": 456, "category": "Diet", "text": "Hara hachi bu: eat until you are eight parts in ten full, then stop. The Okinawan habit builds a built-in calorie buffer without counting anything.", "source": "Okinawan practice — Blue Zones"},
  {"id": 457, "category": "Diet", "text": "Fullness signals take about twenty minutes to reach your brain. Eat fast and you blow past satisfied before the message arrives. Slowing down is portion control that requires no willpower.", "source": "Satiety research — eating rate"},
  {"id": 458, "category": "Diet", "text": "Liquid calories don't register. Sugary drinks deliver hundreds of calories without triggering the fullness response that the same calories in solid food would — your body simply fails to compensate.", "source": "Beverage satiety research"},
  {"id": 459, "category": "Diet", "text": "Whole fruit and fruit juice are different foods. The fruit delivers fibre, slow sugar release, and fullness; the juice delivers the sugar of several fruits in seconds with none of the brakes.", "source": "Nutrition science — fruit vs juice"},
  {"id": 460, "category": "Diet", "text": "Alcohol is a sleep thief disguised as a nightcap. It sedates you into unconsciousness faster but fragments the second half of the night and suppresses REM sleep — you wake unrefreshed and blame everything else.", "source": "Matthew Walker — Why We Sleep"},
  {"id": 461, "category": "Diet", "text": "When you eat matters far less than what and how much. Meal timing tweaks are worth pennies; total intake and food quality are worth pounds. Get the big levers right before optimising the small ones.", "source": "Nutrition science — energy balance"},
  {"id": 462, "category": "Diet", "text": "The best diet is the one you can stick to. Every eating pattern works in a twelve-week study; almost none survive contact with year two. Adherence is the active ingredient.", "source": "Diet adherence research"},
  {"id": 463, "category": "Diet", "text": "In the PREDIMED trial, a Mediterranean diet with olive oil or nuts cut major cardiovascular events by about 30% compared with a low-fat diet — one of the strongest results ever shown for a way of eating.", "source": "PREDIMED trial, Spain"},
  {"id": 464, "category": "Diet", "text": "A handful of nuts most days is one of the most consistent findings in nutrition: lower heart disease, lower all-cause mortality. Calorie-dense, yes — but they crowd out worse snacks and keep you full.", "source": "Nut consumption meta-analyses"},
  {"id": 465, "category": "Diet", "text": "Oily fish twice a week — salmon, mackerel, sardines — delivers omega-3 fats your body can't make, linked to heart and brain health. If a nutrient has to arrive by fork, make room for the fork.", "source": "Omega-3 research — dietary guidelines"},
  {"id": 466, "category": "Diet", "text": "Cooking at home is the biggest single lever. Home cooks eat fewer calories, less sugar, and less ultra-processed food without trying — restaurant and packaged meals are engineered for more of all three.", "source": "Home cooking research"},
  {"id": 467, "category": "Diet", "text": "Hyperpalatable food is engineered — fat, sugar, and salt layered at ratios rarely found in nature, tuned to override fullness. You're not weak; the product is doing exactly what it was designed to do.", "source": "David Kessler — The End of Overeating"},
  {"id": 468, "category": "Diet", "text": "Design your food environment instead of relying on willpower. What's visible on the counter gets eaten; what requires effort gets skipped. Make the good choice the lazy choice.", "source": "Behavioural science — environment design"},
  {"id": 469, "category": "AI Prompting", "text": "Specify the output format before you describe the task. 'Give me a five-row table with columns X, Y, Z' beats a paragraph of wishes. Models match structure far more reliably than they infer it.", "source": "Prompting practice — output specification"},
  {"id": 470, "category": "AI Prompting", "text": "Show, don't just tell. Two or three examples of the input-output pattern you want — few-shot prompting — routinely beats long descriptions of it. The model learns the shape from the samples.", "source": "Few-shot prompting research"},
  {"id": 471, "category": "AI Prompting", "text": "Give the model a role and a situation: 'You are a sceptical CFO reviewing this pitch' produces sharper output than 'review this pitch'. Context activates the right knowledge and tone.", "source": "Prompting practice — role assignment"},
  {"id": 472, "category": "AI Prompting", "text": "Ask the model to reason step by step before answering. Working through the logic in the open catches errors that jumping straight to a conclusion hides — for the model and for you reading it.", "source": "Chain-of-thought prompting research"},
  {"id": 473, "category": "AI Prompting", "text": "Treat the first output as a first draft, never a final answer. The real work of prompting is the second and third turn: 'shorter', 'more sceptical', 'now attack your own reasoning'. Iteration is the method.", "source": "Prompting practice — iteration"},
  {"id": 474, "category": "AI Prompting", "text": "Paste the actual documents in. A model working from your real contract, data, or code beats a model working from your summary of it. Context you provide is worth more than knowledge it retrieves.", "source": "Prompting practice — context provision"},
  {"id": 475, "category": "AI Prompting", "text": "Define what good looks like. 'Write it well' means nothing; 'clear enough that a new hire could follow it without asking questions' is a target the model can aim at and you can check against.", "source": "Prompting practice — success criteria"},
  {"id": 476, "category": "AI Prompting", "text": "Constraints sharpen output. Word limits, banned phrases, required structure, a fixed audience — every constraint you add removes a way the answer can drift into generic filler.", "source": "Prompting practice — constraints"},
  {"id": 477, "category": "AI Prompting", "text": "Tell the model to ask you clarifying questions before it starts. One prompt line — 'ask me anything you need to know first' — surfaces the ambiguities you didn't know your request contained.", "source": "Prompting practice — clarification"},
  {"id": 478, "category": "AI Prompting", "text": "Use clear structure to separate instructions from content — XML tags, headers, or delimiters. When the task, the context, and the examples are visually distinct blocks, the model stops confusing one for another.", "source": "Anthropic prompting guidance"},
  {"id": 479, "category": "AI Prompting", "text": "Say what to do, not what to avoid. 'Write in short, plain sentences' works better than 'don't be verbose'. Negative instructions make the model think about the very thing you're steering away from.", "source": "Prompting practice — positive framing"},
  {"id": 480, "category": "AI Prompting", "text": "Chain the work: outline first, then draft, then critique, then revise — as separate steps. Each stage checked before the next beats one giant prompt asking for a finished masterpiece.", "source": "Prompting practice — task chaining"},
  {"id": 481, "category": "AI Prompting", "text": "Ask for three versions, not one. Requesting alternatives — one safe, one bold, one weird — costs nothing and turns the model from an oracle into a menu. You choose; it generates.", "source": "Prompting practice — alternatives"},
  {"id": 482, "category": "AI Prompting", "text": "Add a self-critique pass: 'Now review your answer. What's weakest? What did you assume? What would a critic say?' Models catch a surprising share of their own errors when explicitly asked to look.", "source": "Prompting practice — self-critique"},
  {"id": 483, "category": "AI Prompting", "text": "Name the audience. An explanation for a ten-year-old, a domain expert, or a busy executive are three different documents. Without an audience the model writes for nobody in particular.", "source": "Prompting practice — audience"},
  {"id": 484, "category": "AI Prompting", "text": "To get your voice, feed it your voice. Paste two or three samples of your own writing and say 'match this style'. Style transfer from examples beats any list of adjectives about tone.", "source": "Prompting practice — voice samples"},
  {"id": 485, "category": "AI Prompting", "text": "Vague in, vague out. A one-line prompt gets a generic answer not because the model is lazy but because a thousand different answers fit your question. Specificity is how you pick one.", "source": "Prompting practice — specificity"},
  {"id": 486, "category": "AI Prompting", "text": "Treat the model like a brilliant intern with amnesia: enormously capable, zero memory of your business, your standards, or yesterday's conversation. Every prompt must carry the context a new hire would need.", "source": "Prompting mental models"},
  {"id": 487, "category": "AI Prompting", "text": "Confidence is not correctness. Models state errors in the same fluent, assured tone as facts. Verify anything that matters — names, numbers, dates, citations — before it leaves your desk.", "source": "AI literacy — verification"},
  {"id": 488, "category": "AI Prompting", "text": "Ask the model to argue against you. 'Steelman the opposite view' or 'make the strongest case that I'm wrong' turns a yes-machine into a sparring partner — and exposes holes before reality does.", "source": "Prompting practice — steelmanning"},
  {"id": 489, "category": "AI Prompting", "text": "Watch your leading questions. Ask 'why is this a great idea?' and the model will happily tell you. Ask 'evaluate this idea' and you might learn something. Models mirror the frame you hand them.", "source": "Prompting practice — framing bias"},
  {"id": 490, "category": "AI Prompting", "text": "Break big asks into small steps. 'Build me a business plan' produces mush; 'first, list the five key assumptions this business depends on' produces something you can work with. Decomposition is the skill.", "source": "Prompting practice — decomposition"},
  {"id": 491, "category": "AI Prompting", "text": "Paste the whole error message. Not your summary of it, not 'it's broken' — the full traceback, verbatim. The model debugs from the exact text far better than from your interpretation of it.", "source": "Prompting practice — debugging"},
  {"id": 492, "category": "AI Prompting", "text": "End hard problems with: 'What am I not asking that I should be?' The model's map of the problem is different from yours, and the gap between the two maps is where the insight usually sits.", "source": "Prompting practice — blind spots"},
  {"id": 493, "category": "AI Prompting", "text": "Flip the direction: have it quiz you. 'Ask me ten hard questions about this chapter' turns passive reading into active recall — the single best-evidenced study technique there is.", "source": "Prompting practice — active recall"},
  {"id": 494, "category": "AI Prompting", "text": "Before a complex task, ask the model to restate the job in its own words. Thirty seconds of 'here's what I understand you want' catches misreadings before they cost you a full generation.", "source": "Prompting practice — task restatement"},
  {"id": 495, "category": "AI Prompting", "text": "A prompt is a specification, not a wish. The same discipline that makes good briefs for humans — context, constraints, examples, success criteria — makes good prompts. Bad delegation fails with any intelligence.", "source": "Prompting mental models"},
  {"id": 496, "category": "AI Prompting", "text": "Save your winning prompts. A prompt that took five iterations to get right is a reusable asset. A personal library of proven prompts compounds like any other tool collection.", "source": "Prompting practice — prompt libraries"},
  {"id": 497, "category": "AI Prompting", "text": "State the date, the place, and the situation. The model doesn't know it's a Tuesday in September, that you're in the UK, or that the deadline is Friday — unless you say so. Unstated context is invisible context.", "source": "Prompting practice — situational context"},
  {"id": 498, "category": "AI Prompting", "text": "Put the critical instruction at the start and repeat it at the end. In long prompts, the middle is where instructions go to be forgotten — models weight the edges, and so do people.", "source": "Prompting practice — instruction placement"},
  {"id": 499, "category": "AI Prompting", "text": "Ask for confidence levels. 'Mark each claim high, medium, or low confidence' makes the model's uncertainty visible instead of smoothed over — and tells you exactly where to check its work.", "source": "Prompting practice — calibration"},
  {"id": 500, "category": "AI Prompting", "text": "Run a premortem with it: 'Assume this plan failed twelve months from now. Write the story of what went wrong.' The model generates failure modes your optimism filtered out.", "source": "Prompting practice — premortems"}
];
